insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('f8d8bwnmba', 'daily:wuerzburg-dom:1610-michael-kern-the-younger-pulpit-of-w-rzburg-cathedral', 'Pulpit of Würzburg Cathedral', 'Michael Kern the Younger', 1610, '1609–1610', null, null, 'Würzburg Cathedral (Kiliansdom)', 3, 'sculpture', 'https://nambatu.github.io/circart-preview/art/f8d8bwnmba.jpg', 'Michael Kern the Younger carved this pulpit in 1609 and 1610. For centuries the sermon came from up here, above the heads of the congregation.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('unmv9rqja6', 'daily:wuerzburg-dom:1981-andreas-moritz-menorah', 'Menorah', 'Andreas Moritz', 1981, null, null, 'metal', 'Würzburg Cathedral (Kiliansdom)', 3, 'object', 'https://nambatu.github.io/circart-preview/art/unmv9rqja6.jpg', 'The seven-branched candelabrum stands in the middle of the nave. Andreas Moritz made it in 1981.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('2hat3rgzjg', 'daily:wuerzburg-dom:1499-tilman-riemenschneider-tomb-of-prince-bishop-rudolf-von-scheren', 'Tomb of Prince-Bishop Rudolf von Scherenberg', 'Tilman Riemenschneider', 1499, '1496–1499', null, 'marble', 'Würzburg Cathedral (Kiliansdom)', 2, 'sculpture', 'https://nambatu.github.io/circart-preview/art/2hat3rgzjg.jpg', 'Rudolf von Scherenberg died in 1495, and Riemenschneider got the commission a year later. The marble monument went up in 1499 and shows the bishop as a very old man, wrinkles and all.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('38up9vv29h', 'daily:wuerzburg-dom:1623-michael-kern-attributed-tomb-of-jakob-baur-von-eiseneck', 'Tomb of Jakob Baur von Eiseneck', 'Michael Kern (attributed)', 1623, '1623, attributed to Michael Kern', null, null, 'Würzburg Cathedral (Kiliansdom)', 3, 'sculpture', 'https://nambatu.github.io/circart-preview/art/38up9vv29h.jpg', 'Jakob Baur von Eiseneck was a colonel in the prince-bishop''s service. He died in July 1621 near Rozvadov in Bohemia, early in the Thirty Years'' War, and his tomb followed in 1623.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('d8dw8kcehs', 'daily:wuerzburg-dom:1279-master-eckart-of-worms-baptismal-font', 'Baptismal font', 'Master Eckart of Worms', 1279, null, null, null, 'Würzburg Cathedral (Kiliansdom)', 3, 'object', 'https://nambatu.github.io/circart-preview/art/d8dw8kcehs.jpg', 'Master Eckart from Worms made this font in 1279. Its sides are covered with figures and scenes, so it is worth walking all the way round it.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('hs4nuryjuw', 'daily:wuerzburg-dom:1706-giovanni-pietro-magni-stucco-ceiling-of-the-crossing', 'Stucco ceiling of the crossing', 'Giovanni Pietro Magni', 1706, '1701–1706', 'Baroque', 'stucco', 'Würzburg Cathedral (Kiliansdom)', 3, 'architecture', 'https://nambatu.github.io/circart-preview/art/hs4nuryjuw.jpg', 'Giovanni Pietro Magni and a team of stucco workers from Ticino covered the church in baroque decoration between 1701 and 1706. The plain walls of the old church disappeared under swirls of white and gold.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('smb836nzqh', 'daily:wuerzburg-dom:1420-unknown-master-piet', 'Pietà', 'Unknown master', 1420, 'around 1410–1420 (sources differ)', 'International Gothic', null, 'Würzburg Cathedral (Kiliansdom)', 3, 'sculpture', 'https://nambatu.github.io/circart-preview/art/smb836nzqh.jpg', 'Mary holds her dead son on her lap. The sources date this Pietà to around 1410 to 1420 and name no sculptor.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('u8kyytsg6y', 'daily:wuerzburg-dom:1967-otto-sonnleitner-kilian-portal', 'Kilian Portal', 'Otto Sonnleitner', 1967, null, null, 'portal', 'Würzburg Cathedral (Kiliansdom)', 3, 'architecture', 'https://nambatu.github.io/circart-preview/art/u8kyytsg6y.jpg', 'Otto Sonnleitner made this portal in 1967, the year the rebuilt cathedral was consecrated again. Since then the church has been dedicated to Kilian and his companions.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('esdap5vn63', 'daily:wuerzburg-dom:1736-balthasar-neumann-sch-nborn-chapel', 'Schönborn Chapel', 'Balthasar Neumann', 1736, '1721–1736', 'Baroque', null, 'Würzburg Cathedral (Kiliansdom)', 2, 'architecture', 'https://nambatu.github.io/circart-preview/art/esdap5vn63.jpg', 'Balthasar Neumann began the burial chapel of the Schönborn family in 1721. The shell stood by 1724, and the chapel was finished in 1736.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('7acmeaj58r', 'daily:wuerzburg-dom:1075-bishops-bruno-and-adalbero-w-rzburg-cathedral', 'Würzburg Cathedral', 'Bishops Bruno and Adalbero', 1075, 'built 1040–1075', null, 'building', 'Würzburg Cathedral (Kiliansdom)', 2, 'architecture', 'https://nambatu.github.io/circart-preview/art/7acmeaj58r.jpg', 'Bishop Bruno started the church in 1040, and it was finished under Bishop Adalbero in 1075. Two older cathedrals had stood here before it, and both were damaged by fire.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de, artist_bonus, movement_bonus, look_back) values ('2026-11-07', 'wuerzburg-dom', 'One cathedral, many centuries', 'Ein Dom, viele Jahrhunderte', 'Today we walk through Würzburg Cathedral. Nearly a thousand years of art stand side by side in it, from the Middle Ages to after the war. We start at the pulpit and walk down the middle of the nave towards a tall candelabrum.', 'Heute gehen wir durch den Würzburger Dom. Darin stehen fast tausend Jahre Kunst nebeneinander, vom Mittelalter bis nach dem Krieg. Wir beginnen an der Kanzel und gehen durch die Mitte des Langhauses auf einen hohen Leuchter zu.', 'On 16 March 1945 bombs and fire hit the cathedral, and in February 1946 its north wall collapsed. The rebuilt church was consecrated again on 6 May 1967. That is why old and new art stand so close together here today.', 'Am 16. März 1945 trafen Bomben und Feuer den Dom, und im Februar 1946 stürzte seine Nordwand ein. Am 6. Mai 1967 wurde die wiederaufgebaute Kirche neu geweiht. Deshalb stehen alte und neue Kunst hier heute so dicht beieinander.', true, true, false) on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, artist_bonus = excluded.artist_bonus, movement_bonus = excluded.movement_bonus, look_back = excluded.look_back, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 0, 'f8d8bwnmba', null, null, 'Photo: Holger Uwe Schmitt, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 1, 'unmv9rqja6', 'Now walk along the pillars on the left, where the prince-bishops keep watch.', 'Geh jetzt an den Pfeilern links entlang, wo die Fürstbischöfe Wache halten.', 'Photo: José Luiz, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 2, '2hat3rgzjg', 'Riemenschneider lived and worked in Würzburg, and he is buried in the city too. A few pillars on, a soldier waits.', 'Riemenschneider lebte und arbeitete in Würzburg und ist auch hier begraben. Ein paar Pfeiler weiter wartet ein Soldat.', 'Photo: Holger Uwe Schmitt, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 3, '38up9vv29h', 'It was probably carved by Michael Kern, from the same family of sculptors as the pulpit. Now cross over to the font, where the city''s children are baptised.', 'Vermutlich stammt es von Michael Kern, aus derselben Bildhauerfamilie wie die Kanzel. Jetzt geht es hinüber zum Taufbecken, an dem die Kinder der Stadt getauft werden.', 'Photo: Nilaxus, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 4, 'd8dw8kcehs', 'From the font we look straight up, to the white ceiling over the crossing.', 'Vom Taufbecken aus schauen wir direkt nach oben, zur weißen Decke über der Vierung.', 'Photo: Holger Uwe Schmitt, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 5, 'hs4nuryjuw', 'Below all that white and gold sits a quiet figure of grief in front of a golden wall.', 'Unter all dem Weiß und Gold sitzt eine stille Figur der Trauer vor einer goldenen Wand.', 'Photo: José Luiz, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 6, 'smb836nzqh', 'Now we step outside for a moment, to the side door on Kiliansplatz.', 'Jetzt gehen wir kurz hinaus, zum Seitenportal am Kiliansplatz.', 'Photo: Klaus Bärwinkel, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 7, 'u8kyytsg6y', 'Back inside, the north transept leads into a chapel built for one powerful family.', 'Zurück drinnen führt das nördliche Querhaus in eine Kapelle, die für eine mächtige Familie gebaut wurde.', 'Photo: Dietmar Rabich, CC BY-SA 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 8, 'esdap5vn63', 'Through the chapel we leave the cathedral. Turn around one last time and look at the whole church.', 'Durch die Kapelle verlassen wir den Dom. Dreh dich ein letztes Mal um und schau dir die ganze Kirche an.', 'Photo: Dguendel, CC BY 4.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-07', 9, '7acmeaj58r', 'And that is the end of our walk.', 'Damit endet unser Rundgang.', 'Photo: Imaschke, CC BY-SA 4.0');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('7drh4hwm49', 'daily:written-out:1705-maria-sibylla-merian-spiders-ants-and-a-hummingbird-on-a-guav', 'Spiders, ants and a hummingbird on a guava branch (Metamorphosis insectorum Surinamensium)', 'Maria Sibylla Merian', 1705, 'published in Amsterdam in 1705', null, 'hand-coloured engraving', 'Metamorphosis insectorum Surinamensium (book)', 2, 'drawing', 'https://nambatu.github.io/circart-preview/art/7drh4hwm49.jpg', 'Maria Sibylla Merian sailed to Suriname with her daughter Dorothea to watch insects grow up on their own plants. Back in Amsterdam she published her big book about them in 1705.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('4uwrrhee7q', 'daily:written-out:1555-sofonisba-anguissola-the-chess-game', 'The Chess Game', 'Sofonisba Anguissola', 1555, null, 'Mannerism', 'oil on canvas', 'National Museum, Poznań', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/4uwrrhee7q.jpg', 'Sofonisba Anguissola painted three of her sisters at a game of chess while a maid looks on. She signed and dated the picture on the edge of the chessboard.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('mj9ubupv5k', 'daily:written-out:1907-hilma-af-klint-the-ten-largest-no-7-adulthood', 'The Ten Largest, No. 7, Adulthood', 'Hilma af Klint', 1907, null, 'Abstract art', 'tempera on paper mounted on canvas', 'Hilma af Klint Foundation, Stockholm', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/mj9ubupv5k.jpg', 'This painting is more than three metres tall. It belongs to a series of ten about the ages of a human life, from childhood to old age.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('g9dab98dr3', 'daily:written-out:1630-judith-leyster-self-portrait', 'Self-Portrait', 'Judith Leyster', 1630, 'about 1630', 'Dutch Golden Age', 'oil on canvas', 'National Gallery of Art, Washington', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/g9dab98dr3.jpg', 'Judith Leyster turns round from her easel as if you had just walked into her studio. She was one of very few women in the Haarlem painters'' guild and had pupils of her own.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('7a5wukj2sf', 'daily:written-out:1855-rosa-bonheur-the-horse-fair', 'The Horse Fair', 'Rosa Bonheur', 1855, '1852–1855', 'Realism', 'oil on canvas', 'The Metropolitan Museum of Art, New York', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/7a5wukj2sf.jpg', 'The canvas is about five metres wide. To study the horses at the Paris horse market, Rosa Bonheur went there in men''s clothes, which in her day needed a police permit.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('rh87rnegar', 'daily:written-out:1577-lavinia-fontana-self-portrait-at-the-clavichord-with-a-s', 'Self-Portrait at the Clavichord with a Servant', 'Lavinia Fontana', 1577, null, 'Mannerism', 'oil on canvas', 'Accademia Nazionale di San Luca, Rome', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/rh87rnegar.jpg', 'Lavinia Fontana shows herself playing music while a maid holds the sheet music. The picture says: this painter is also an educated young woman.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('ra4mnf79wu', 'daily:written-out:1772-johan-zoffany-the-academicians-of-the-royal-academy', 'The Academicians of the Royal Academy', 'Johan Zoffany', 1772, '1771–1772', null, 'oil on canvas', 'Royal Collection, Windsor', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/ra4mnf79wu.jpg', 'The members of the new Royal Academy in London gather around a nude model in the life class. Two founding members are women, Angelica Kauffman and Mary Moser, but they only appear as small portraits on the wall.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('dm8kz25pp6', 'daily:written-out:1639-artemisia-gentileschi-self-portrait-as-the-allegory-of-paintin', 'Self-Portrait as the Allegory of Painting', 'Artemisia Gentileschi', 1639, '1638–1639', 'Baroque', 'oil on canvas', 'Royal Collection, Hampton Court Palace', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/dm8kz25pp6.jpg', 'Artemisia Gentileschi painted herself as the figure of Painting, brush in hand and hard at work. She probably made it during her stay in England, and King Charles I owned it.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('tk34mfb7dj', 'daily:written-out:1872-berthe-morisot-the-cradle', 'The Cradle', 'Berthe Morisot', 1872, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/tk34mfb7dj.jpg', 'Berthe Morisot painted her sister Edma watching over her sleeping baby, Blanche. The picture hung in the first Impressionist exhibition.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('8cyrccbgzw', 'daily:written-out:1782-lisabeth-vig-e-le-brun-self-portrait-in-a-straw-hat', 'Self-Portrait in a Straw Hat', 'Élisabeth Vigée Le Brun', 1782, 'after 1782', null, 'oil on canvas', 'National Gallery, London', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/8cyrccbgzw.jpg', 'On a trip to Flanders Élisabeth Vigée Le Brun saw Rubens'' portrait of a woman in a straw hat and painted her own answer to it. She became Queen Marie Antoinette''s favourite portrait painter.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de, artist_bonus, movement_bonus, look_back) values ('2026-11-08', 'written-out', 'Written out of the picture', 'Aus dem Bild gedrängt', 'Today''s ten pictures were all made by women, except one, and that one tells you a lot. Each of these women was famous in her day and was then pushed to the edge of the frame. Your start card is a page from Maria Sibylla Merian''s insect book. The first picture to place shows three sisters at a chessboard.', 'Die zehn Bilder von heute haben alle Frauen gemacht, bis auf eins, und genau das verrät viel. Jede dieser Frauen war zu Lebzeiten berühmt und wurde danach an den Bildrand gedrängt. Deine Startkarte ist eine Seite aus Maria Sibylla Merians Insektenbuch. Das erste Bild zum Einordnen zeigt drei Schwestern am Schachbrett.', 'Every woman today was celebrated in her lifetime, and many of them then went missing from the big art history books. Museums around the world are now bringing them back into the picture, one exhibition at a time.', 'Jede Frau von heute wurde zu Lebzeiten gefeiert, und viele verschwanden danach aus den großen Kunstgeschichtsbüchern. Museen auf der ganzen Welt holen sie jetzt zurück ins Bild, eine Ausstellung nach der anderen.', true, true, false) on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, artist_bonus = excluded.artist_bonus, movement_bonus = excluded.movement_bonus, look_back = excluded.look_back, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 0, '7drh4hwm49', null, null, 'Maria Sibylla Merian, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 1, '4uwrrhee7q', 'Sofonisba went on to work at the Spanish court and painted the royal family. Our next painter chose to hide her boldest pictures herself.', 'Sofonisba arbeitete dann am spanischen Hof und malte die Königsfamilie. Unsere nächste Malerin hat ihre kühnsten Bilder selbst versteckt.', 'Sofonisba Anguissola, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 2, 'mj9ubupv5k', 'Hilma af Klint asked that her abstract work stay hidden for twenty years following her death, so the world met it very late. The next painter vanished in another way: under a famous man''s name.', 'Hilma af Klint wollte, dass ihre abstrakten Bilder bis zwanzig Jahre nach ihrem Tod verborgen bleiben, und so lernte die Welt sie erst sehr spät kennen. Die nächste Malerin verschwand auf andere Weise: unter dem Namen eines berühmten Mannes.', 'Hilma af Klint, public domain (photo: Hilma af Klint Foundation, via Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 3, 'g9dab98dr3', 'For a long time Leyster''s pictures were sold as works by Frans Hals, and only in 1893 was she rediscovered. The next painter made sure nobody could overlook her: she painted big.', 'Lange wurden Leysters Bilder als Werke von Frans Hals verkauft, erst 1893 wurde sie wiederentdeckt. Die nächste Malerin sorgte dafür, dass niemand sie übersehen konnte: Sie malte riesig.', 'National Gallery of Art, Washington, CC0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 4, '7a5wukj2sf', 'Rosa Bonheur became the first woman artist to receive the Legion of Honour. From the noisy horse market we go to a quiet room, where a young woman sits at a keyboard.', 'Rosa Bonheur bekam als erste Künstlerin das Kreuz der Ehrenlegion. Vom lauten Pferdemarkt geht es in einen stillen Raum, in dem eine junge Frau an einem Tasteninstrument sitzt.', 'The Metropolitan Museum of Art, public domain');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 5, 'rh87rnegar', 'Lavinia Fontana went on to Rome as a sought-after portrait painter while raising a large family. Next comes the one picture by a man today. Look closely at who is missing.', 'Lavinia Fontana zog als gefragte Porträtmalerin nach Rom und zog nebenbei eine große Familie groß. Jetzt kommt das einzige Bild eines Mannes heute. Schau genau hin, wer fehlt.', 'Lavinia Fontana, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 6, 'ra4mnf79wu', 'A lady was not allowed into the life class, so the two women could only hang on the wall. The next woman put herself right in the middle of the picture, as Painting itself.', 'Eine Dame durfte beim Aktzeichnen nicht dabei sein, also konnten die beiden Frauen nur an der Wand hängen. Die nächste Frau hat sich mitten ins Bild gesetzt, als die Malerei selbst.', 'Johan Zoffany, public domain (Royal Collection, via Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 7, 'dm8kz25pp6', 'Artemisia was famous across Europe in her lifetime, and then she almost disappeared from the books. Our next painter turned her brush on her own family.', 'Artemisia war zu Lebzeiten in ganz Europa berühmt und verschwand danach fast aus den Büchern. Unsere nächste Malerin hat ihre eigene Familie gemalt.', 'Artemisia Gentileschi, public domain (Royal Collection, via Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 8, 'tk34mfb7dj', 'Morisot took part in nearly every Impressionist exhibition. Our final picture is a self-portrait in a straw hat.', 'Morisot war bei fast allen Ausstellungen der Impressionisten dabei. Unser letztes Bild ist ein Selbstporträt mit Strohhut.', 'Musée d''Orsay, public domain (Google Art Project, via Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-08', 9, '8cyrccbgzw', 'And that is the end of our gallery.', 'Damit endet unser Rundgang durch die Galerie.', 'National Gallery, London, public domain (Wikimedia Commons)');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('wwgwkshzxs', 'daily:saint-martin:1567-pieter-bruegel-the-elder-the-wine-of-saint-martin-s-day', 'The Wine of Saint Martin''s Day', 'Pieter Bruegel the Elder', 1567, '1566–1567 (Prado); Wikipedia gives c. 1565–1568', 'Northern Renaissance', 'glue-size tempera on linen', 'Museo del Prado, Madrid', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/wwgwkshzxs.jpg', 'A whole village crowds round a barrel of new wine, and somewhere in the throng St Martin quietly shares his cloak. Experts found traces of Bruegel''s signature on it in 2010, and the Prado bought the picture that same year.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('uxjczc23qj', 'daily:saint-martin:1317-simone-martini-saint-martin-shares-his-cloak-with-a-beg', 'Saint Martin Shares His Cloak with a Beggar', 'Simone Martini', 1317, 'the chapel frescoes are undated; about 1313–1318 (Wikipedia), about 1316–1317 (Key to Umbria)', 'Sienese School', 'fresco', 'San Martino Chapel, Lower Basilica of San Francesco, Assisi', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/uxjczc23qj.jpg', 'This scene opens a series of ten frescoes about Martin''s life in a chapel of the Lower Basilica in Assisi. A cardinal paid for the chapel, but Simone Martini neither signed nor dated his paintings.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('8267g92wvy', 'daily:saint-martin:1599-el-greco-saint-martin-and-the-beggar', 'Saint Martin and the Beggar', 'El Greco', 1599, '1597–1599', 'Mannerism', 'oil on canvas', 'National Gallery of Art, Washington', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/8267g92wvy.jpg', 'Martín Ramírez, who shared the saint''s name, ordered this picture for his chapel of San José in Toledo. It stayed there for about three hundred years before it went to America.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('t3n2tp76g6', 'daily:saint-martin:1240-naumburg-master-attributed-bassenheim-rider', 'Bassenheim Rider', 'Naumburg Master (attributed)', 1240, 'about 1240: the plaque in Bassenheim says 1239, the regional tourism site says the master worked in Mainz around 1250', null, 'sandstone relief', 'Parish church of St Martin, Bassenheim', 3, 'sculpture', 'https://nambatu.github.io/circart-preview/art/t3n2tp76g6.jpg', 'This grey sandstone relief is attributed to the Naumburg Master, one of the great sculptors of the Middle Ages. Martin cuts his cloak with his sword while the beggar already holds on to it.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('f6xavxx6wj', 'daily:saint-martin:1900-gebhard-fugel-saint-martin-and-the-beggar', 'Saint Martin and the Beggar', 'Gebhard Fugel', 1900, '1900 (Commons); Panorama Altötting dates his murals in the Wangen town church to 1899', null, 'ceiling painting', 'Parish church of St Martin, Wangen im Allgäu', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/f6xavxx6wj.jpg', 'Gebhard Fugel painted this scene on the ceiling of St Martin''s church in Wangen im Allgäu. He was born near Ravensburg, not far away, and painted churches in southern Germany and Austria.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('gnznszywvc', 'daily:saint-martin:1475-martin-schongauer-saint-martin-dividing-his-cloak', 'Saint Martin Dividing His Cloak', 'Martin Schongauer', 1475, 'about 1475', 'Late Gothic', 'engraving', 'National Gallery of Art, Washington', 3, 'drawing', 'https://nambatu.github.io/circart-preview/art/gnznszywvc.jpg', 'This engraving is only about fifteen centimetres tall. Because it was printed from an engraved metal plate, the same little Martin could be printed again and again.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('2vezsr9kp2', 'daily:saint-martin:1620-anthony-van-dyck-saint-martin-dividing-his-cloak', 'Saint Martin Dividing his Cloak', 'Anthony van Dyck', 1620, 'about 1618–1620 (Royal Collection); Wikipedia gives about 1620', 'Baroque', 'oil on canvas', 'Royal Collection, Windsor Castle', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/2vezsr9kp2.jpg', 'Van Dyck painted a smaller version of this scene for the church in Zaventem near Brussels, and it still hangs there. This bigger one, more than two metres wide, belongs to the British Royal Collection.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de, artist_bonus, movement_bonus, look_back) values ('2026-11-11', 'saint-martin', 'Half a cloak', 'Ein halber Mantel', 'Today is St Martin''s Day, and children all over the country walk with lanterns. We follow one moment that artists never got tired of: a young soldier cuts his cloak in half for a freezing beggar. Your start card is a wild village feast in Martin''s honour, and the first picture to place takes you to a chapel in Italy.', 'Heute ist Martinstag, und überall ziehen Kinder mit Laternen durch die Straßen. Wir folgen einem Moment, von dem Künstler nie genug bekamen: Ein junger Soldat teilt seinen Mantel für einen frierenden Bettler. Deine Startkarte ist ein wildes Dorffest zu Martins Ehren, und das erste Bild zum Einordnen führt dich in eine Kapelle in Italien.', 'Every age dressed Martin and his beggar in its own way, but the gesture stayed the same. Tonight his story lives on in lantern walks and in many a roast goose.', 'Jede Zeit hat Martin und seinen Bettler auf ihre eigene Weise gekleidet, doch die Geste blieb dieselbe. Heute Abend lebt seine Geschichte in Laternenumzügen weiter und in so mancher Martinsgans.', true, true, false) on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, artist_bonus = excluded.artist_bonus, movement_bonus = excluded.movement_bonus, look_back = excluded.look_back, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 0, 'wwgwkshzxs', null, null, 'Museo del Prado, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 1, 'uxjczc23qj', 'Simone Martini painted Martin''s whole life on these chapel walls. Next we travel to Toledo in Spain, where a man called Martín wanted his patron saint over his altar.', 'Simone Martini hat Martins ganzes Leben an diese Kapellenwände gemalt. Als Nächstes reisen wir nach Toledo in Spanien, wo ein Mann namens Martín seinen Namenspatron über dem Altar haben wollte.', 'Simone Martini, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 2, '8267g92wvy', 'El Greco puts Martin in shining armour on a white horse, high above the beggar. Our next Martin is not painted at all: he is carved in stone.', 'El Greco setzt Martin in glänzender Rüstung auf ein weißes Pferd, hoch über den Bettler. Unser nächster Martin ist gar nicht gemalt: Er ist in Stein gehauen.', 'National Gallery of Art, Washington, CC0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 3, 't3n2tp76g6', 'In 1683 the rider came to the village of Bassenheim, and he still lives in its parish church. Now look up: our next Martin rides across a church ceiling in the Allgäu.', '1683 kam der Reiter in das Dorf Bassenheim, und er wohnt bis heute in der Pfarrkirche dort. Jetzt schau nach oben: Unser nächster Martin reitet über eine Kirchendecke im Allgäu.', 'Photo: Lothar Spurzem, CC BY-SA 2.0 de');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 4, 'f6xavxx6wj', 'Fugel also painted a giant panorama of the Crucifixion for Altötting. Our next Martin is tiny by comparison: he fits on a sheet of paper smaller than your hand.', 'Fugel malte auch ein riesiges Panorama der Kreuzigung für Altötting. Unser nächster Martin ist dagegen winzig: Er passt auf ein Blatt Papier, das kleiner ist als deine Hand.', 'Gebhard Fugel, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 5, 'gnznszywvc', 'Schongauer shared his name with the saint, a nice coincidence for this card. Our final Martin comes from Antwerp, a city full of painters.', 'Schongauer trug denselben Vornamen wie der Heilige, ein schöner Zufall für diese Karte. Unser letzter Martin kommt aus Antwerpen, einer Stadt voller Maler.', 'National Gallery of Art, Washington, CC0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-11', 6, '2vezsr9kp2', 'And with that, our lantern walk ends.', 'Damit endet unser Laternenumzug.', 'Royal Collection Trust, public domain (Wikimedia Commons)');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('rp9jsftwzf', 'daily:stolen:1633-rembrandt-the-storm-on-the-sea-of-galilee', 'The Storm on the Sea of Galilee', 'Rembrandt', 1633, null, 'Dutch Golden Age', 'oil on canvas', 'Stolen from the Isabella Stewart Gardner Museum, Boston (whereabouts unknown)', 1, 'destroyed_or_lost', 'https://nambatu.github.io/circart-preview/art/rp9jsftwzf.jpg', 'Rembrandt''s only seascape – and nobody has seen it in public for decades. It was stolen in the largest art heist in US history, when thieves posing as police officers walked out of the Gardner Museum with thirteen works. Among the panicking disciples, one man looks straight out at you: Rembrandt himself.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('qfss9crjpx', 'daily:stolen:1503-leonardo-da-vinci-mona-lisa', 'Mona Lisa', 'Leonardo da Vinci', 1503, 'c. 1503-1506', 'High Renaissance', 'oil on poplar', 'Louvre, Paris', 1, 'object', 'https://nambatu.github.io/circart-preview/art/qfss9crjpx.jpg', 'It was a moderately admired picture until 1911, when a Louvre handyman named Vincenzo Peruggia walked out with it under his coat. The empty wall drew larger crowds than the painting ever had, Picasso was questioned as a suspect, and by the time it came back two years later it was the most famous object in the world. Fame was retroactive. Leonardo also never delivered it to whoever commissioned it, carrying it around for over a decade instead.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('g6vx5k7rdm', 'daily:stolen:1893-edvard-munch-the-scream', 'The Scream', 'Edvard Munch', 1893, null, 'Expressionism', 'tempera and crayon on cardboard', 'National Gallery, Oslo', 1, 'object', 'https://nambatu.github.io/circart-preview/art/g6vx5k7rdm.jpg', 'Munch''s diary records walking at sunset when the sky turned blood red and he felt an infinite scream passing through nature, and researchers have suggested the colour came from Krakatoa ash, which produced spectacular red skies over Europe for months. The figure is not screaming but blocking out a scream. In the top left corner, in tiny pencil, someone wrote that it could only have been painted by a madman; 2021 analysis confirmed the handwriting is Munch''s own.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('xpwajjqect', 'daily:stolen:1432-jan-van-eyck-the-ghent-altarpiece', 'The Ghent Altarpiece', 'Jan van Eyck', 1432, null, 'Northern Renaissance', 'oil on panel', 'Saint Bavo Cathedral, Ghent', 2, 'object', 'https://nambatu.github.io/circart-preview/art/xpwajjqect.jpg', 'The most frequently stolen artwork in history, by some distance. It has been burned at, dismembered, ransomed by Napoleon, handed over as a First World War reparation, hidden in an Austrian salt mine by the Nazis and rescued by the Monuments Men. One panel taken in 1934 has never been found and is still represented by a copy. Recent cleaning also removed centuries of overpaint from the Mystic Lamb, revealing an unnervingly humanoid face with forward-set eyes that briefly went viral.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('3w2qrw53zx', 'daily:stolen:1814-francisco-goya-portrait-of-the-duke-of-wellington', 'Portrait of the Duke of Wellington', 'Francisco Goya', 1814, 'painted in 1812 and reworked until 1814 (National Gallery: 1812–14)', 'Romanticism', 'oil on mahogany', 'National Gallery, London', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/3w2qrw53zx.jpg', 'Goya painted the British general in Madrid, right after Wellington had driven the French army out of the city. When Wellington won more honours, Goya went back to the picture and added them to the uniform.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('cxftepb2uu', 'daily:stolen:1672-johannes-vermeer-the-guitar-player', 'The Guitar Player', 'Johannes Vermeer', 1672, 'not dated; about 1672 (Kenwood, Wikipedia), about 1670–1673 (Essential Vermeer)', 'Dutch Golden Age', 'oil on canvas', 'Kenwood House, London', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/cxftepb2uu.jpg', 'A young woman looks up from her guitar and smiles at someone we can''t see. When Vermeer died, his widow handed this picture to the family''s baker as a pledge for a large unpaid bread bill.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('cfsqjq6a52', 'daily:stolen:1882-vincent-van-gogh-view-of-the-sea-at-scheveningen', 'View of the Sea at Scheveningen', 'Vincent van Gogh', 1882, 'August 1882', null, 'oil on canvas', 'Van Gogh Museum, Amsterdam', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/cfsqjq6a52.jpg', 'Van Gogh set up his easel on the beach in the middle of a storm. The wind blew so hard that grains of sand stuck in the wet paint, and some of them are still there.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de, artist_bonus, movement_bonus, look_back) values ('2026-11-13', 'stolen', 'Bad luck, good luck', 'Pech und Glück', 'It''s Friday the 13th, so today''s paintings all had a very bad day once: each of them was stolen. Some came home in the strangest ways, and two are still missing. Your start card is a famous empty frame in Boston, and the first picture to place once left the Louvre in Paris without anyone noticing.', 'Heute ist Freitag, der 13., also hatte jedes Bild von heute schon einmal einen richtig schlechten Tag: Alle wurden gestohlen. Manche kamen auf den seltsamsten Wegen zurück, und zwei sind bis heute verschwunden. Deine Startkarte ist ein berühmter leerer Rahmen in Boston, und das erste Bild zum Einordnen verließ einst den Louvre in Paris, ohne dass es jemand bemerkte.', 'Five of today''s works are safely home, and the great altarpiece in Ghent is still waiting for one panel. Rembrandt''s storm is out there somewhere, and in Boston its empty frame still hangs on the wall. Luckily, bad luck doesn''t always last.', 'Fünf der heutigen Werke sind wieder sicher zu Hause, und der große Altar in Gent wartet noch auf eine Tafel. Rembrandts Sturm ist irgendwo da draußen, und in Boston hängt sein leerer Rahmen noch immer an der Wand. Zum Glück hält Pech nicht ewig.', true, true, false) on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, artist_bonus = excluded.artist_bonus, movement_bonus = excluded.movement_bonus, look_back = excluded.look_back, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-13', 0, 'rp9jsftwzf', null, null, 'Rembrandt, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-13', 1, 'qfss9crjpx', 'In 1911 a Louvre worker simply carried her out under his coat, and for two years nobody knew where she was. Her disappearance made her the most famous painting in the world. Our next picture was taken on a morning when all of Norway was watching the Olympics.', '1911 trug ein Arbeiter des Louvre sie einfach unter seinem Mantel hinaus, und zwei Jahre lang wusste niemand, wo sie war. Erst durch ihr Verschwinden wurde sie zum berühmtesten Bild der Welt. Unser nächstes Bild verschwand an einem Morgen, an dem ganz Norwegen auf die Olympischen Spiele schaute.', 'Leonardo da Vinci, public domain (C2RMF / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-13', 2, 'g6vx5k7rdm', 'Two men leaned a ladder against the museum wall and were gone in under a minute. They even left a note that thanked the museum for the poor security. Three months on the police had the picture back, unharmed. The next work holds a sad record, because no other artwork has been stolen so often.', 'Zwei Männer lehnten eine Leiter an die Museumswand und waren nach nicht einmal einer Minute wieder weg. Sie hinterließen sogar einen Zettel und bedankten sich für die schlechte Bewachung. Drei Monate danach hatte die Polizei das Bild unversehrt zurück. Das nächste Werk hält einen traurigen Rekord, denn kein anderes Kunstwerk wurde so oft gestohlen.', 'Edvard Munch, public domain (Nasjonalmuseet / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-13', 3, 'xpwajjqect', 'Napoleon''s soldiers carried parts of it off to Paris, and in the Second World War it was hidden deep inside an Austrian salt mine until Allied soldiers found it. One panel was taken in 1934 and never came back, so a copy stands in its place. Our next thief wanted something much smaller, and that was free television.', 'Napoleons Soldaten schleppten Teile davon nach Paris, und im Zweiten Weltkrieg lag der Altar tief in einem österreichischen Salzbergwerk, bis alliierte Soldaten ihn fanden. Eine Tafel wurde 1934 gestohlen und kam nie zurück, deshalb steht an ihrer Stelle eine Kopie. Unser nächster Dieb wollte etwas viel Kleineres, nämlich kostenloses Fernsehen.', 'Jan and Hubert van Eyck, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-13', 4, '3w2qrw53zx', 'The man who confessed was a former bus driver who wanted free TV for pensioners. While the police searched, a copy of the painting even had a cameo in a James Bond film, hanging in the villain''s lair. Next we visit a grand house on the edge of a London park.', 'Gestanden hat ein ehemaliger Busfahrer, der sich kostenloses Fernsehen für Rentner wünschte. Während die Polizei suchte, hatte eine Kopie des Bildes sogar einen Auftritt in einem James-Bond-Film, an der Wand im Versteck des Bösewichts. Als Nächstes besuchen wir ein herrschaftliches Haus am Rand eines Londoner Parks.', 'Francisco Goya, public domain (National Gallery / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-13', 5, 'cxftepb2uu', 'A ransom note demanded that two sisters, jailed for an IRA bombing in London, be moved to a prison in Northern Ireland. Nobody gave in. Ten weeks on, the painting stood in a London churchyard, leaning against a gravestone and wrapped in newspaper. For our last picture we climb onto a museum roof in Amsterdam.', 'In einem Erpresserbrief hieß es, zwei Schwestern sollten nach Nordirland verlegt werden, die wegen eines IRA-Bombenanschlags in London im Gefängnis saßen. Niemand gab nach. Zehn Wochen danach stand das Bild auf einem Londoner Kirchhof, an einen Grabstein gelehnt und in Zeitungspapier gewickelt. Für unser letztes Bild klettern wir auf ein Museumsdach in Amsterdam.', 'Johannes Vermeer, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-13', 6, 'cfsqjq6a52', 'Two thieves climbed a ladder to the museum roof, smashed a window and left with this picture and one more. It took fourteen years until Italian police found both of them near Naples, in the hands of the Camorra. Today the stormy sea hangs on its wall in Amsterdam again.', 'Zwei Diebe stiegen mit einer Leiter aufs Museumsdach, schlugen ein Fenster ein und nahmen dieses Bild und noch ein weiteres mit. Es dauerte vierzehn Jahre, bis die italienische Polizei beide bei Neapel fand, in den Händen der Camorra. Heute hängt das stürmische Meer wieder an seiner Wand in Amsterdam.', 'Vincent van Gogh, public domain (Van Gogh Museum / Wikimedia Commons)');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('wz89wq6adr', 'daily:monet:1877-claude-monet-the-saint-lazare-station', 'The Saint-Lazare Station', 'Claude Monet', 1877, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, 'object', 'https://nambatu.github.io/circart-preview/art/wz89wq6adr.jpg', 'Monet got permission to paint inside the busy Paris station and made about a dozen views of it. The story goes that trains were held back and stoked so he could catch the steam. Here the subject is really the smoke and light, with the trains as supporting actors.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('wcaxn6rn33', 'daily:monet:1866-claude-monet-camille-the-woman-in-the-green-dress', 'Camille (The Woman in the Green Dress)', 'Claude Monet', 1866, null, null, 'oil on canvas', 'Kunsthalle Bremen', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/wcaxn6rn33.jpg', 'Monet had planned a huge picnic scene for the Paris Salon, but he could not finish it in time. So he sent this portrait of his model Camille Doncieux instead. The jury accepted it, and the critics were full of praise for its fresh style.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('hwsdjchggp', 'daily:monet:1899-claude-monet-the-japanese-footbridge', 'The Japanese Footbridge', 'Claude Monet', 1899, null, 'Impressionism', 'oil on canvas', 'National Gallery of Art, Washington, D.C.', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/hwsdjchggp.jpg', 'The bridge stood in Monet''s own garden in the village of Giverny. He designed the garden himself and had a small stream diverted to feed the lily pond. He painted this same view twelve times in a single year.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('asreeqmju6', 'daily:monet:1872-claude-monet-impression-sunrise', 'Impression, Sunrise', 'Claude Monet', 1872, null, 'Impressionism', 'oil on canvas', 'Musée Marmottan Monet, Paris', 1, 'object', 'https://nambatu.github.io/circart-preview/art/asreeqmju6.jpg', 'A hostile critic named Louis Leroy wrote a mocking review built around the title, saying that wallpaper in its embryonic state was more finished, and coined Impressionism as an insult. The group adopted it within a couple of years. Astronomers have since analysed the tide, the smoke direction and the sun''s altitude and dated the scene to around 7:35am on 13 November 1872. It was stolen in 1985 and recovered five years later.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('kb7s7myzru', 'daily:monet:1879-claude-monet-camille-monet-on-her-deathbed', 'Camille Monet on Her Deathbed', 'Claude Monet', 1879, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/kb7s7myzru.jpg', 'Camille died in the village of Vétheuil at the age of 32, after a long illness. Monet painted her one last time. He told a friend that he had caught himself studying the colours on her face, and that it had shocked him.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('kekmxvsqbx', 'daily:monet:1875-claude-monet-woman-with-a-parasol-madame-monet-and-he', 'Woman with a Parasol – Madame Monet and Her Son', 'Claude Monet', 1875, null, 'Impressionism', 'oil on canvas', 'National Gallery of Art, Washington, D.C.', 1, 'object', 'https://nambatu.github.io/circart-preview/art/kekmxvsqbx.jpg', 'Monet painted his wife Camille and their son Jean on a windy summer day near Argenteuil. He worked outdoors and fast, probably in a single session of a few hours. You can almost feel the breeze in her veil.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('vnmb2sh6h7', 'daily:monet:1906-claude-monet-water-lilies', 'Water Lilies', 'Claude Monet', 1906, 'signed and dated 1906', 'Impressionism', 'oil on canvas', 'Art Institute of Chicago', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/vnmb2sh6h7.jpg', 'There is no bank, no bridge and no sky in this picture. Monet looks only at the surface of his pond, so the sky and the trees appear just as reflections between the lily pads. He showed 48 of these water pictures together in Paris.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('59xxuxm4qg', 'daily:monet:1894-claude-monet-rouen-cathedral-the-portal-in-full-sunli', 'Rouen Cathedral, the Portal in Full Sunlight', 'Claude Monet', 1894, 'painted in Rouen in 1893, finished in the studio and dated 1894 (Musée d''Orsay)', 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/59xxuxm4qg.jpg', 'Monet rented a room across the square from the cathedral and worked on many canvases at once. He swapped them as the light moved over the stone. This one shows the front in full sunlight, and its other name is "Harmony in Blue and Gold".', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de, artist_bonus, movement_bonus, look_back) values ('2026-11-14', 'monet', 'Monet''s life in eight pictures', 'Monets Leben in acht Bildern', 'Claude Monet was born in Paris on 14 November 1840. Today we follow his life through eight of his own pictures, from a young painter with empty pockets to the gardener of Giverny. Your start card is a railway station full of steam, and the first picture to place shows the woman who would change his life.', 'Claude Monet kam am 14. November 1840 in Paris zur Welt. Heute folgen wir seinem Leben durch acht seiner eigenen Bilder, vom jungen Maler mit leeren Taschen bis zum Gärtner von Giverny. Deine Startkarte ist ein Bahnhof voller Dampf, und das erste Bild zum Einordnen zeigt die Frau, die sein Leben verändern sollte.', 'Monet went on painting his pond until he died in Giverny in 1926, at the age of 86. His house and garden are open to visitors, and the water lilies still bloom there every summer. Happy birthday, Claude.', 'Monet malte seinen Teich, bis er 1926 mit 86 Jahren in Giverny starb. Sein Haus und sein Garten stehen Besuchern offen, und die Seerosen blühen dort noch jeden Sommer. Alles Gute zum Geburtstag, Claude.', false, false, false) on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, artist_bonus = excluded.artist_bonus, movement_bonus = excluded.movement_bonus, look_back = excluded.look_back, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-14', 0, 'wz89wq6adr', null, null, 'Claude Monet, public domain (Google Art Project / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-14', 1, 'wcaxn6rn33', 'The woman in the green dress was a young studio model when she met Monet, and she became his wife. You will meet her again today. Our next picture leaves Paris far behind: a little green bridge over a pond.', 'Die Frau im grünen Kleid war ein junges Malermodell, als sie Monet kennenlernte, und sie wurde seine Frau. Du triffst sie heute noch einmal wieder. Unser nächstes Bild lässt Paris weit hinter sich: eine kleine grüne Brücke über einem Teich.', 'Claude Monet, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-14', 2, 'hwsdjchggp', 'In Giverny Monet found the home where he stayed for the rest of his life, and he turned its garden into his favourite subject. For the next picture we go to the harbour of Le Havre, the town where he grew up, on a misty morning.', 'In Giverny fand Monet das Zuhause, in dem er bis an sein Lebensende blieb, und dessen Garten machte er zu seinem liebsten Motiv. Für das nächste Bild gehen wir an einem nebligen Morgen in den Hafen von Le Havre, der Stadt, in der er aufwuchs.', 'Claude Monet, public domain (National Gallery of Art, Washington / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-14', 3, 'asreeqmju6', 'This little harbour view gave a whole movement its name. Fame did not pay the bills, though, and the family often had to borrow money. The next picture is the saddest one he ever painted.', 'Dieser kleine Hafenblick gab einer ganzen Bewegung ihren Namen. Die Rechnungen bezahlte der Ruhm aber nicht, und die Familie musste sich oft Geld leihen. Das nächste Bild ist das traurigste, das er je gemalt hat.', 'Claude Monet, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-14', 4, 'kb7s7myzru', 'Monet was left with two sons and very little money. To remember Camille as he knew her, our next picture is full of wind and sunshine: a woman with a parasol on a hill.', 'Monet blieb mit zwei Söhnen und sehr wenig Geld zurück. Damit wir Camille so in Erinnerung behalten, wie er sie kannte, ist unser nächstes Bild voller Wind und Sonne: eine Frau mit Sonnenschirm auf einem Hügel.', 'Claude Monet, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-14', 5, 'kekmxvsqbx', 'In many of Monet''s best-known pictures there are no people at all, and that makes this one special. In the next one there is nothing but water and flowers.', 'Auf vielen von Monets bekanntesten Bildern ist gar kein Mensch zu sehen, und das macht dieses hier besonders. Im nächsten gibt es nur noch Wasser und Blüten.', 'Claude Monet, public domain (Google Art Project / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-14', 6, 'vnmb2sh6h7', 'Monet painted his pond around 250 times, and the canvases grew until they filled whole rooms. But one subject was never enough for him, because what he was really after was the light. Our last picture is the stone front of a great church, and he painted it more than thirty times.', 'Rund 250 Mal malte Monet seinen Teich, und die Leinwände wurden immer größer, bis sie ganze Räume füllten. Ein Motiv allein war ihm aber nie genug, denn eigentlich ging es ihm um das Licht. Unser letztes Bild ist die steinerne Fassade einer großen Kirche, und er malte sie mehr als dreißig Mal.', 'Claude Monet, public domain (Art Institute of Chicago / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-14', 7, '59xxuxm4qg', 'Twenty of the cathedral pictures went on show together in Paris: the same church front in twenty kinds of light. The painter with the empty pockets had become one of the most famous artists in France.', 'Zwanzig der Kathedralenbilder wurden zusammen in Paris ausgestellt: dieselbe Kirchenfassade in zwanzig Arten von Licht. Aus dem Maler mit den leeren Taschen war einer der berühmtesten Künstler Frankreichs geworden.', 'Claude Monet, public domain (Wikimedia Commons)');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('jz7qdrkayf', 'daily:skull:1630-pieter-claesz-vanitas-still-life', 'Vanitas Still Life', 'Pieter Claesz', 1630, null, null, 'oil on panel', 'Mauritshuis, The Hague', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/jz7qdrkayf.jpg', 'Everything on this table carries the same message. The light has just gone out, the glass has tipped over and the watch keeps ticking. Claesz put his initials and the date on the book, as if they were written into its pages.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('xs8xx9jzr9', 'daily:skull:1533-hans-holbein-the-younger-the-ambassadors', 'The Ambassadors', 'Hans Holbein the Younger', 1533, null, 'Northern Renaissance', 'oil on oak', 'National Gallery, London', 2, 'object', 'https://nambatu.github.io/circart-preview/art/xs8xx9jzr9.jpg', 'The grey smear across the floor resolves into a perfect human skull if you stand at the lower right edge of the frame, which is exactly where you end up if the painting hangs beside a staircase. Everything in the picture is a status object: globes, sundials, a lute, a Lutheran hymn book. One lute string is broken. It is a portrait of two young men at the height of their powers with death drawn diagonally across the carpet.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('gh9mkbwkze', 'daily:skull:1886-vincent-van-gogh-head-of-a-skeleton-with-a-burning-cigare', 'Head of a Skeleton with a Burning Cigarette', 'Vincent van Gogh', 1886, 'winter 1885–86; the Van Gogh Museum dates it to early 1886', null, 'oil on canvas', 'Van Gogh Museum, Amsterdam', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/gh9mkbwkze.jpg', 'Small as it is, this picture shows how well Van Gogh had learned his anatomy. The canvas is hardly bigger than a sheet of writing paper.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('aa4sbjjjav', 'daily:skull:1427-masaccio-holy-trinity', 'Holy Trinity', 'Masaccio', 1427, null, 'Early Renaissance', 'fresco', 'Santa Maria Novella, Florence', 3, 'object', 'https://nambatu.github.io/circart-preview/art/aa4sbjjjav.jpg', 'The painted barrel vault was so convincing that contemporaries described walking up to the wall to check whether the chapel was real. It is the first surviving painting built on a mathematically consistent one-point perspective scheme, executed just a few years after Brunelleschi worked out the system. At the bottom, a skeleton on a tomb carries an inscription telling the viewer that what you are, I once was, and what I am, you will be. Renaissance painting begins with a memento mori and a magic trick in the same picture.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('drdz63m2fb', 'daily:skull:1872-arnold-b-cklin-self-portrait-with-death-playing-the-fid', 'Self-Portrait with Death Playing the Fiddle', 'Arnold Böcklin', 1872, null, null, 'oil on canvas', 'Alte Nationalgalerie, Berlin', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/drdz63m2fb.jpg', 'Böcklin painted this in Munich and showed it there the same year. Alma Mahler said that her husband Gustav was under the spell of this picture when he wrote the scherzo of his Fourth Symphony.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('veeduuyz53', 'daily:skull:1521-albrecht-d-rer-saint-jerome', 'Saint Jerome', 'Albrecht Dürer', 1521, 'painted on Dürer''s journey to the Netherlands, 1520–21; finished in March 1521', null, 'oil on panel', 'Museu Nacional de Arte Antiga, Lisbon', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/veeduuyz53.jpg', 'For the saint''s face Dürer drew an old man he met in the Netherlands. The drawing is kept in Vienna today, and on it Dürer noted the man''s age: 93.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('e54qhj6vnt', 'daily:skull:1651-david-bailly-vanitas-still-life-with-portrait-of-a-yo', 'Vanitas Still Life with Portrait of a Young Painter', 'David Bailly', 1651, null, null, 'oil on panel', 'Museum De Lakenhal, Leiden', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/e54qhj6vnt.jpg', 'Behind the tall glass you can make out the faint face of a woman. The museum thinks she may be Bailly''s wife. This is the last work of his that we know.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de, artist_bonus, movement_bonus, look_back) values ('2026-11-15', 'skull', 'The skull on the table', 'Der Schädel auf dem Tisch', 'November is the month for remembering, and painters have always had a favourite way of doing it: they put a skull in the picture. It isn''t there to scare you. It is a small reminder that time is short, so enjoy it. Your start card is a Dutch table with a skull on it, and the first picture to place hides its skull so well that you could walk right past it.', 'Der November ist der Monat des Erinnerns, und Maler hatten dafür schon immer ein Lieblingsmittel: Sie malten einen Schädel ins Bild. Er soll dir keine Angst machen. Er erinnert nur freundlich daran, dass die Zeit kurz ist und du sie genießen sollst. Deine Startkarte ist ein holländischer Tisch mit einem Schädel darauf, und das erste Bild zum Einordnen versteckt seinen Schädel so gut, dass du glatt daran vorbeilaufen könntest.', 'Seven pictures, and not one of these skulls wanted to frighten you. Each one says the same friendly thing in its own voice: your time is precious. Critics of Böcklin''s day had a lovely name for that. They called it “memento vivere”, remember to live. That sounds like a good plan for a Sunday in November.', 'Sieben Bilder, und keiner dieser Schädel wollte dir Angst machen. Jeder sagt auf seine Art dasselbe Freundliche: Deine Zeit ist kostbar. Kritiker zu Böcklins Zeit hatten dafür einen schönen Namen. Sie nannten es „Memento vivere“, denk daran zu leben. Das klingt nach einem guten Plan für einen Sonntag im November.', true, true, false) on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, artist_bonus = excluded.artist_bonus, movement_bonus = excluded.movement_bonus, look_back = excluded.look_back, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-15', 0, 'jz7qdrkayf', null, null, 'Pieter Claesz, public domain (Mauritshuis / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-15', 1, 'xs8xx9jzr9', 'These two friends are still in their twenties, and they seem to have everything a person could wish for. Holbein gave them two secrets. One is the skull, which you only find when you walk to the right-hand edge of the picture. The other is a tiny crucifix that peeps out from behind the green curtain at the top left. Our next skull takes it all far less seriously: it is having a smoke.', 'Die beiden Freunde sind noch keine dreißig und scheinen alles zu haben, was man sich wünschen kann. Holbein hat ihnen zwei Geheimnisse mitgegeben. Das eine ist der Schädel, den du erst findest, wenn du an den rechten Bildrand gehst. Das andere ist ein winziges Kruzifix, das oben links hinter dem grünen Vorhang hervorschaut. Unser nächster Schädel nimmt das alles viel lockerer: Er raucht erst mal eine.', 'Hans Holbein the Younger, public domain (Google Art Project / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-15', 2, 'gh9mkbwkze', 'Van Gogh painted this while he was a student at the art academy in Antwerp. Drawing skeletons was a normal exercise there, but painting one with a cigarette was certainly not on the timetable. He loved to smoke himself, so this is a student''s joke and no warning at all. Our next skeleton has something to say to you. It lies at the foot of a church wall in Florence.', 'Van Gogh malte das Bild, als er an der Kunstakademie in Antwerpen studierte. Skelette zu zeichnen war dort eine ganz normale Übung, aber eines mit Zigarette zu malen stand sicher nicht auf dem Stundenplan. Er rauchte selbst leidenschaftlich gern, also ist das ein Studentenwitz und keine Warnung. Unser nächstes Skelett hat dir etwas zu sagen. Es liegt am Fuß einer Kirchenwand in Florenz.', 'Vincent van Gogh, public domain (Google Art Project / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-15', 3, 'aa4sbjjjav', 'This skeleton talks to everyone who walks past, and then it fell silent for a very long time. In 1570 Giorgio Vasari set a stone altar in front of the wall, and the whole fresco disappeared behind it. The skeleton was only found again under the plaster in 1952. Our next painter does not read about death. He hears it, because someone is playing the fiddle right behind him.', 'Dieses Skelett spricht jeden an, der vorbeigeht, und dann blieb es sehr lange stumm. 1570 stellte Giorgio Vasari einen Steinaltar vor die Wand, und das ganze Fresko verschwand dahinter. Das Skelett fand man erst 1952 unter dem Putz wieder. Unser nächster Maler liest nichts über den Tod. Er hört ihn, denn direkt hinter ihm spielt jemand Geige.', 'Masaccio, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-15', 4, 'drdz63m2fb', 'Böcklin has stopped painting to listen. Behind him Death plays a fiddle that has only one string left. He doesn''t look frightened, more like someone who has just had an idea, and the museum in Berlin reads it exactly that way: Death is not his enemy here, he brings the inspiration. In our next picture an old man lays his finger on a skull and looks you straight in the eye.', 'Böcklin hält beim Malen inne und lauscht. Hinter ihm spielt der Tod auf einer Geige, die nur noch eine Saite hat. Erschrocken sieht er nicht aus, eher wie jemand, dem gerade etwas eingefallen ist, und genau so liest es auch das Museum in Berlin: Der Tod ist hier kein Feind, er bringt die Eingebung. Auf unserem nächsten Bild legt ein alter Mann den Finger auf einen Schädel und schaut dir direkt in die Augen.', 'Arnold Böcklin, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-15', 5, 'veeduuyz53', 'The old man is Saint Jerome, the great scholar among the saints. He looks up from his books, and his finger on the skull asks you a quiet question: what are you doing with your time? Dürer painted him on a journey through the Netherlands and gave the picture to a Portuguese trade envoy there, which is why it hangs in Lisbon today. For our last picture a painter lays out his whole life on one table.', 'Der alte Mann ist der heilige Hieronymus, der große Gelehrte unter den Heiligen. Er blickt von seinen Büchern auf, und sein Finger auf dem Schädel stellt dir leise eine Frage: Was machst du mit deiner Zeit? Dürer malte ihn auf einer Reise durch die Niederlande und schenkte das Bild dort einem portugiesischen Handelsgesandten, und deshalb hängt es heute in Lissabon. Für unser letztes Bild breitet ein Maler sein ganzes Leben auf einem Tisch aus.', 'Albrecht Dürer, public domain (The Yorck Project / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-15', 6, 'e54qhj6vnt', 'A young painter holds up a small oval portrait of an old man. The old man is David Bailly himself, and nobody knows for sure who the young one is. He may well be Bailly too, as he once looked. So one man meets himself across a table full of soap bubbles and coins, with a skull among them and a slip of paper that says everything is vanity.', 'Ein junger Maler hält ein kleines ovales Bildnis eines alten Mannes hoch. Der alte Mann ist David Bailly selbst, und wer der junge ist, weiß niemand genau. Gut möglich, dass auch er Bailly ist, so wie er einmal aussah. So begegnet ein Mann sich selbst an einem Tisch voller Seifenblasen und Münzen, mit einem Schädel dazwischen und einem Zettel, auf dem steht, dass alles eitel ist.', 'David Bailly, public domain (Museum De Lakenhal / Wikimedia Commons)');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('bg3z6dt752', 'daily:hammer:1835-j-m-w-turner-rome-from-mount-aventine', 'Rome, from Mount Aventine', 'J.M.W. Turner', 1835, 'Painted in 1835, first shown at the Royal Academy in 1836.', 'Romanticism', 'oil on canvas', 'Private collection', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/bg3z6dt752.jpg', 'Turner painted this view of Rome for the collector Hugh Munro of Novar. He worked from drawings he had made in the city in 1828. The picture was shown at the Royal Academy in London in 1836.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('zfefcnhtr4', 'daily:hammer:1500-leonardo-da-vinci-salvator-mundi', 'Salvator Mundi', 'Leonardo da Vinci', 1500, 'About 1500 (Christie''s 2017, NPR, Wikipedia''s list of most expensive paintings). The exact year is not known.', 'High Renaissance', 'oil on walnut', 'Private collection', 1, 'painting', 'https://nambatu.github.io/circart-preview/art/zfefcnhtr4.jpg', 'Christ raises one hand in blessing and holds a crystal globe in the other. The picture has been cleaned and restored, and experts still argue about how much of it Leonardo painted himself.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('4bz3mnu22k', 'daily:hammer:1919-claude-monet-le-bassin-aux-nymph-as', 'Le Bassin aux Nymphéas', 'Claude Monet', 1919, null, 'Impressionism', 'oil on canvas', 'Private collection', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/4bz3mnu22k.jpg', 'Monet painted the water-lily pond in his garden in Giverny again and again. This canvas is two metres wide, and the Paris dealers Bernheim-Jeune bought it from him the very year he painted it.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('e748f3awe3', 'daily:hammer:1612-peter-paul-rubens-the-massacre-of-the-innocents', 'The Massacre of the Innocents', 'Peter Paul Rubens', 1612, 'About 1611–12 (Wikipedia article, The Culture Trip on the Art Gallery of Ontario). Wikipedia''s list of most expensive paintings says 1611, the article''s info box 1609–11.', 'Baroque', 'oil painting', 'Art Gallery of Ontario, Toronto', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/e748f3awe3.jpg', 'Rubens painted this scene from the Bible soon after he came home to Antwerp from Italy. King Herod''s soldiers have come for the children of Bethlehem, and the mothers fight back with their bare hands.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('9suhap82pv', 'daily:hammer:1890-vincent-van-gogh-portrait-of-dr-gachet', 'Portrait of Dr. Gachet', 'Vincent van Gogh', 1890, 'First version, painted in June 1890 in Auvers-sur-Oise.', 'Post-Impressionism', 'oil on canvas', 'Private collection (whereabouts unknown)', 1, 'painting', 'https://nambatu.github.io/circart-preview/art/9suhap82pv.jpg', 'Paul Gachet was van Gogh''s doctor in Auvers-sur-Oise. Van Gogh painted him in June, leaning on a table with his head propped on his hand. The Städel in Frankfurt bought the picture in 1911 and lost it in 1937, when it was confiscated as “degenerate art”.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('5wt496ttp6', 'daily:hammer:1658-rembrandt-portrait-of-a-man-with-arms-akimbo', 'Portrait of a Man with Arms Akimbo', 'Rembrandt', 1658, 'Signed and dated 1658.', 'Dutch Golden Age', 'oil on canvas', 'Agnes Etherington Art Centre, Kingston (Canada)', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/5wt496ttp6.jpg', 'The man stands with his hands on his hips and looks straight at you. Rembrandt signed and dated the picture. Today it belongs to the Agnes Etherington Art Centre at Queen''s University in Kingston, Canada.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('hskfwrfed2', 'daily:hammer:1881-douard-manet-spring-jeanne', 'Spring (Jeanne)', 'Édouard Manet', 1881, null, 'Impressionism', 'oil on canvas', 'J. Paul Getty Museum, Los Angeles', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/hskfwrfed2.jpg', 'The model was a young Paris actress whose stage name was Demarsy. Manet wanted to paint a series of the four seasons, but he did not live to finish it.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de, artist_bonus, movement_bonus, look_back) values ('2026-11-16', 'hammer', 'Under the hammer', 'Unter dem Hammer', 'Today''s pictures have one thing in common: each of them once made an auction room hold its breath. You place them by the year they were painted, and after each one you hear what happened when it was sold. Your start card is a view of Rome by Turner. It had only ever changed owners once when it set a record for the painter in London. The first picture to place holds the biggest record of them all.', 'Die Bilder von heute haben eines gemeinsam: Bei jedem hielt einmal ein ganzer Auktionssaal den Atem an. Du ordnest sie nach dem Jahr ein, in dem sie gemalt wurden, und nach jedem Bild erfährst du, was bei seinem Verkauf geschah. Deine Startkarte ist ein Blick auf Rom von Turner. Das Bild hatte erst ein einziges Mal den Besitzer gewechselt, als es in London einen Rekord für den Maler aufstellte. Das erste Bild zum Einordnen hält den größten Rekord von allen.', 'Seven pictures, and together they cost well over a billion dollars in today''s money. The happiest endings are the ones in a museum. The Rubens hangs in Toronto and the Manet in Los Angeles, where anyone can go and look at them. The doctor, though, is still missing. More record breakers will follow soon.', 'Sieben Bilder, und zusammen haben sie in heutigem Geld weit über eine Milliarde Dollar gekostet. Am schönsten sind die Geschichten, die im Museum enden. Der Rubens hängt in Toronto und der Manet in Los Angeles, wo jeder sie ansehen kann. Der Doktor dagegen bleibt verschwunden. Bald folgen weitere Rekordbilder.', true, true, false) on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, artist_bonus = excluded.artist_bonus, movement_bonus = excluded.movement_bonus, look_back = excluded.look_back, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-16', 0, 'bg3z6dt752', null, null, 'J.M.W. Turner, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-16', 1, 'zfefcnhtr4', 'No painting has ever cost more at an auction. The bidding in New York started at 75 million dollars and went on for nineteen minutes, with gasps all through the room. The final price was 450 million dollars, which is about 590 million in today''s money. In 1958 the same picture had gone for 45 pounds. Our next picture is much calmer: a pond full of flowers.', 'Kein Gemälde war je auf einer Auktion teurer. In New York begann das Bieten bei 75 Millionen Dollar und dauerte neunzehn Minuten, und im Saal schnappten die Leute immer wieder nach Luft. Am Ende standen 450 Millionen Dollar, das sind in heutigem Geld etwa 590 Millionen. 1958 war dasselbe Bild noch für 45 Pfund weggegangen. Unser nächstes Bild ist viel ruhiger: ein Teich voller Blüten.', 'Leonardo da Vinci, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-16', 2, '4bz3mnu22k', 'This pond set a record for Monet in London in 2008. Many collectors fought over it, and the winner was sitting right there in the saleroom. The price was 80 million dollars, about 120 million in today''s money. The same picture had already been sold in New York in 1971, for 320,000 dollars. The next picture is anything but calm, and it used to carry the wrong painter''s name.', 'Dieser Teich stellte 2008 in London einen Rekord für Monet auf. Viele Sammler boten gegeneinander, und der Gewinner saß mitten im Saal. Der Preis lag bei 80 Millionen Dollar, in heutigem Geld sind das etwa 120 Millionen. 1971 war dasselbe Bild in New York schon einmal verkauft worden, für 320.000 Dollar. Das nächste Bild ist alles andere als ruhig, und es trug früher den Namen des falschen Malers.', 'Claude Monet, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-16', 3, 'e748f3awe3', 'For a long time this picture went under other painters'' names. Then in 2001 an expert at Sotheby''s looked at it and was sure: this is a Rubens. In 2002 it sold in London for almost 50 million pounds, which is about 137 million dollars in today''s money. The buyer was the Canadian collector Kenneth Thomson, and he gave it to the Art Gallery of Ontario in Toronto. The next picture shows a doctor with a very sad face.', 'Lange lief dieses Bild unter den Namen anderer Maler. 2001 sah es sich dann ein Experte von Sotheby''s an und war sicher: Das ist ein Rubens. 2002 wurde es in London für fast 50 Millionen Pfund versteigert, in heutigem Geld sind das etwa 137 Millionen Dollar. Der Käufer war der kanadische Sammler Kenneth Thomson, und er schenkte es der Art Gallery of Ontario in Toronto. Das nächste Bild zeigt einen Arzt mit einem sehr traurigen Gesicht.', 'Peter Paul Rubens, public domain (Art Gallery of Ontario / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-16', 4, '9suhap82pv', 'In May 1990 the doctor set a new record for a painting at auction: 82.5 million dollars, about 200 million in today''s money. The buyer was the Japanese businessman Ryoei Saito, and he said he would have the picture cremated with him when he died. He also spoke of giving it to a museum instead. Since his death in 1996 nobody has said in public where it is. The next picture shows a man who looks very sure of himself.', 'Im Mai 1990 stellte der Doktor einen neuen Rekord für ein versteigertes Gemälde auf: 82,5 Millionen Dollar, in heutigem Geld etwa 200 Millionen. Der Käufer war der japanische Unternehmer Ryoei Saito, und er sagte, er wolle das Bild nach seinem Tod mit sich verbrennen lassen. Er sprach aber auch davon, es einem Museum zu geben. Seit seinem Tod 1996 hat niemand öffentlich gesagt, wo es ist. Das nächste Bild zeigt einen Mann, der sich seiner Sache sehr sicher ist.', 'Vincent van Gogh, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-16', 5, '5wt496ttp6', 'Nobody had seen this man in public for almost forty years when he turned up at Christie''s in London in 2009. He sold for a little over 20 million pounds, more than any Rembrandt at auction before him. In 1930 he had cost 18,500 pounds. People used to take him for a Dutch admiral, but since 2021 we know that he was a master carpenter. The last picture shows a young actress with a parasol.', 'Fast vierzig Jahre lang hatte niemand diesen Mann öffentlich gesehen, als er 2009 bei Christie''s in London auftauchte. Er wurde für etwas mehr als 20 Millionen Pfund versteigert, mehr als je zuvor ein Rembrandt auf einer Auktion. 1930 hatte er noch 18.500 Pfund gekostet. Früher hielt man ihn für einen holländischen Admiral, doch seit 2021 weiß man, dass er ein Zimmermeister war. Das letzte Bild zeigt eine junge Schauspielerin mit Sonnenschirm.', 'Rembrandt, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-16', 6, 'hskfwrfed2', 'Manet called this picture “Jeanne” when he showed it at the Paris Salon, and the critics loved it. Then it spent more than a hundred years with one American family. In November 2014 it sold in New York for 65 million dollars. That was almost twice the old record for Manet, and it is about 89 million in today''s money. The buyer was the Getty Museum in Los Angeles, so now anyone can visit her.', 'Manet nannte dieses Bild „Jeanne“, als er es im Pariser Salon zeigte, und die Kritiker liebten es. Dann blieb es mehr als hundert Jahre bei einer amerikanischen Familie. Im November 2014 wurde es in New York für 65 Millionen Dollar versteigert. Das war fast doppelt so viel wie der alte Rekord für Manet, und in heutigem Geld sind es etwa 89 Millionen. Gekauft hat es das Getty Museum in Los Angeles, und dort kann sie jetzt jeder besuchen.', 'Édouard Manet, public domain (J. Paul Getty Museum / Wikimedia Commons)');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('5fcgrjynpv', 'daily:hammer-2:1913-franz-marc-the-foxes', 'The Foxes', 'Franz Marc', 1913, 'Painted in 1913 (Wikipedia, The Art Newspaper).', 'Expressionism', 'oil on canvas', 'Private collection', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/5fcgrjynpv.jpg', 'Two foxes lie curled into each other, broken up into sharp coloured shapes. Marc painted animals for most of his short life. Here he tried out what he had seen in the new French painting of his day.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('br47ny7uks', 'daily:hammer-2:1910-wassily-kandinsky-murnau-with-church-ii', 'Murnau with Church II', 'Wassily Kandinsky', 1910, 'Painted in 1910 (lootedart.com, AP).', 'Expressionism', 'oil on canvas', 'Private collection', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/br47ny7uks.jpg', 'Kandinsky spent several summers in the Bavarian market town of Murnau. In this view the church tower and the houses are already dissolving into patches of pure colour.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('52prx4n878', 'daily:hammer-2:1943-max-beckmann-self-portrait-yellow-pink', 'Self-Portrait Yellow-Pink', 'Max Beckmann', 1943, 'Dated 1943 (Grisebach, AP).', null, 'oil on canvas', 'Private collection', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/52prx4n878.jpg', 'The Nazis branded Beckmann''s art as “degenerate”, and he left Germany for Amsterdam. He painted himself again and again through his whole life. This self-portrait comes from his years in exile.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('bdpgfvj5ja', 'daily:hammer-2:1930-piet-mondrian-composition-no-ii', 'Composition No. II', 'Piet Mondrian', 1930, 'Dated 1930 (Sotheby''s, RKD catalogue no. B219). A slightly smaller sister picture from the same year hangs in the Kunsthaus Zürich.', 'De Stijl', 'oil on canvas', 'Private collection', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/bdpgfvj5ja.jpg', 'Mondrian allowed himself only straight black lines, white and the three primary colours. In this picture one large red field takes up most of the space.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('f4navw42n6', 'daily:hammer-2:1888-georges-seurat-les-poseuses-ensemble-small-version', 'Les Poseuses, Ensemble (small version)', 'Georges Seurat', 1888, 'Painted in 1888 (HENI, Wikipedia''s list of most expensive paintings).', 'Neo-Impressionism', 'oil on canvas', 'Private collection', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/f4navw42n6.jpg', 'Seurat built his pictures out of thousands of tiny dots of colour. This is the small version of a large painting that hangs in the Barnes Foundation in Philadelphia.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('kbjurhbw9r', 'daily:hammer-2:1940-frida-kahlo-the-dream-the-bed', 'The Dream (The Bed)', 'Frida Kahlo', 1940, 'Painted in 1940 (Sotheby''s, NPR, Al Jazeera).', null, 'oil on canvas', 'Private collection', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/kbjurhbw9r.jpg', 'Kahlo painted herself asleep in a wooden bed. After a bus accident at the age of eighteen she spent long stretches of her life lying down.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('v5eds8e7tf', 'daily:hammer-2:1918-amedeo-modigliani-nu-couch-reclining-nude', 'Nu couché (Reclining Nude)', 'Amedeo Modigliani', 1918, '1917–18 according to Christie''s and HENI; Wikipedia''s article says 1917.', null, 'oil on canvas', 'Long Museum, Shanghai', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/v5eds8e7tf.jpg', 'Modigliani painted a whole series of reclining nudes in Paris. This one belonged for decades to the Italian collector Gianni Mattioli and then to his daughter.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('5qh5krfaac', 'daily:hammer-2:1895-edvard-munch-the-scream-pastel', 'The Scream (pastel)', 'Edvard Munch', 1895, 'The pastel of 1895 (Wikipedia''s list of most expensive paintings, AP). The famous painted version in Oslo is from 1893.', 'Expressionism', 'pastel on board', 'Private collection', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/5qh5krfaac.jpg', 'Munch made several versions of The Scream. This is one of two in pastel, and he painted a poem about the blood-red sky onto its frame.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('j5ef9fakj9', 'daily:hammer-2:1916-gustav-klimt-portrait-of-elisabeth-lederer', 'Portrait of Elisabeth Lederer', 'Gustav Klimt', 1916, 'Painted 1914–16 (Sotheby''s); counted by the year it was finished.', 'Art Nouveau', 'oil on canvas', 'Private collection', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/j5ef9fakj9.jpg', 'Elisabeth Lederer was the daughter of August and Serena Lederer, the most important patrons Klimt ever had. He worked on her portrait for about two years.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de, artist_bonus, movement_bonus, look_back) values ('2026-11-18', 'hammer-2', 'Going, going, gone', 'Zum Ersten, zum Zweiten, zum Dritten', 'Part two of our days in the auction room. Today''s pictures are by the modern masters, and each of them broke a record when the hammer fell. You place them by the year they were made. Your start card is Franz Marc''s foxes. They belonged to the banker Kurt Grawi, who had to flee from the Nazis, and the sale of the picture paid for his family''s new start in Chile. In 2021 a German panel advised the city of Düsseldorf to hand the foxes back to his heirs. In 2022 they sold in London for 42.6 million pounds, more than any Marc before. The first picture to place has a very similar story.', 'Teil zwei unserer Tage im Auktionssaal. Die Bilder von heute stammen von den Meistern der Moderne, und jedes brach einen Rekord, als der Hammer fiel. Du ordnest sie nach dem Jahr ein, in dem sie entstanden sind. Deine Startkarte sind die Füchse von Franz Marc. Sie gehörten dem Bankier Kurt Grawi, der vor den Nationalsozialisten fliehen musste, und der Verkauf des Bildes bezahlte den Neuanfang seiner Familie in Chile. 2021 empfahl eine deutsche Kommission der Stadt Düsseldorf, die Füchse seinen Erben zurückzugeben. 2022 wurden sie in London für 42,6 Millionen Pfund versteigert, mehr als je ein Marc zuvor. Das erste Bild zum Einordnen hat eine ganz ähnliche Geschichte.', 'Nine pictures and nine records. Look again at how three of these stories begin, though: with a family that had its pictures taken away or had to leave them behind. The foxes, the village church and the Klimt portrait all had to find their way back before anyone could bid on them. A record price is often just the loud ending of a long and quiet story.', 'Neun Bilder und neun Rekorde. Schau dir aber noch einmal an, wie drei dieser Geschichten anfangen: mit einer Familie, der ihre Bilder weggenommen wurden oder die sie zurücklassen musste. Die Füchse, die Dorfkirche und das Klimt-Bildnis mussten alle erst den Weg zurück finden, bevor jemand auf sie bieten konnte. Ein Rekordpreis ist oft nur das laute Ende einer langen, leisen Geschichte.', true, true, false) on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, artist_bonus = excluded.artist_bonus, movement_bonus = excluded.movement_bonus, look_back = excluded.look_back, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-18', 0, '5fcgrjynpv', null, null, 'Franz Marc, public domain (Google Art Project / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-18', 1, 'br47ny7uks', 'This village view hung for decades in a Dutch museum. Then it was handed back to the family of Johanna Margarete Stern, who had bought it from Kandinsky himself and was murdered in Auschwitz. In 2023 it sold in London for 37.2 million pounds, a record for the painter. Thirteen heirs shared the money, and part of it now pays for the search for the rest of the family''s collection. The next record was set in Berlin, with a picture a painter made of himself.', 'Dieses Dorfbild hing jahrzehntelang in einem niederländischen Museum. Dann ging es zurück an die Familie von Johanna Margarete Stern, die es bei Kandinsky selbst gekauft hatte und in Auschwitz ermordet wurde. 2023 wurde es in London für 37,2 Millionen Pfund versteigert, ein Rekord für den Maler. Dreizehn Erben teilten sich das Geld, und ein Teil davon bezahlt jetzt die Suche nach dem Rest der Sammlung. Der nächste Rekord fiel in Berlin, mit einem Bild, das ein Maler von sich selbst gemalt hat.', 'Wassily Kandinsky, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-18', 2, '52prx4n878', 'Beckmann gave this picture to his wife, and she kept it until she died. In December 2022 it came up for sale in Berlin. After about three minutes a buyer from Switzerland had won it on the phone. With fees he paid 23.2 million euros, the highest price ever paid at an auction in Germany. The next picture gets by with three colours and a few black lines.', 'Beckmann schenkte dieses Bild seiner Frau, und sie behielt es bis zu ihrem Tod. Im Dezember 2022 kam es in Berlin unter den Hammer. Nach etwa drei Minuten hatte ein Käufer aus der Schweiz am Telefon den Zuschlag. Mit Aufgeld zahlte er 23,2 Millionen Euro, den höchsten Preis, der je auf einer Auktion in Deutschland erzielt wurde. Das nächste Bild kommt mit drei Farben und ein paar schwarzen Linien aus.', 'Max Beckmann (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-18', 3, 'bdpgfvj5ja', 'This picture set the record for Mondrian twice. In 1983 it was the first abstract painting to sell for more than two million dollars at an auction. In November 2022 it came back to the auction room in New York and went for 51 million, which beat the old Mondrian record by a whisker. Only five days apart, a much quieter picture made almost three times as much in the same city. It comes next.', 'Dieses Bild hat den Rekord für Mondrian gleich zweimal aufgestellt. 1983 war es das erste abstrakte Gemälde, das auf einer Auktion mehr als zwei Millionen Dollar brachte. Im November 2022 kam es in New York wieder in den Auktionssaal und ging für 51 Millionen weg, haarscharf über dem alten Mondrian-Rekord. Nur fünf Tage lagen dazwischen, als ein viel stilleres Bild in derselben Stadt fast das Dreifache brachte. Es kommt als Nächstes.', 'Piet Mondrian, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-18', 4, 'f4navw42n6', 'Three models pose in the studio, and on the wall behind them you can see a corner of the painter''s most famous picture. This small canvas belonged to Paul Allen, who founded Microsoft together with Bill Gates. When his collection was sold in November 2022 it made 149.2 million dollars, more than four times the old record for Seurat. That is over 170 million in today''s money. The next record belongs to a woman who is fast asleep.', 'Drei Modelle posieren im Atelier, und an der Wand hinter ihnen siehst du eine Ecke vom berühmtesten Bild des Malers. Die kleine Leinwand gehörte Paul Allen, der zusammen mit Bill Gates Microsoft gegründet hat. Als seine Sammlung im November 2022 versteigert wurde, brachte sie 149,2 Millionen Dollar, mehr als das Vierfache des alten Rekords für Seurat. In heutigem Geld sind das über 170 Millionen. Der nächste Rekord gehört einer Frau, die tief und fest schläft.', 'Georges Seurat, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-18', 5, 'kbjurhbw9r', 'Kahlo''s bed floats among the clouds, and on top of it lies a skeleton wired with dynamite. In 1980 this picture cost 51,000 dollars. In November 2025 it sold in New York for 54.7 million, the highest price ever paid at an auction for a work by a woman. The old record had belonged to Georgia O''Keeffe for eleven years. The next picture was bought for a museum in Shanghai.', 'Kahlos Bett schwebt zwischen den Wolken, und obenauf liegt ein Skelett, das mit Dynamit verdrahtet ist. 1980 kostete dieses Bild 51.000 Dollar. Im November 2025 wurde es in New York für 54,7 Millionen versteigert, der höchste Preis, der je auf einer Auktion für das Werk einer Frau gezahlt wurde. Den alten Rekord hatte elf Jahre lang Georgia O''Keeffe gehalten. Das nächste Bild wurde für ein Museum in Shanghai gekauft.', 'Frida Kahlo, © Banco de México Diego Rivera Frida Kahlo Museums Trust (photo: fridakahlo.org)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-18', 6, 'v5eds8e7tf', 'At least seven bidders were still in the race when the price passed 100 million dollars. In the end the Chinese collector Liu Yiqian and his wife Wang Wei won this nude for their Long Museum. They paid 170.4 million dollars in November 2015, which is about 225 million in today''s money. Only one work of art had ever cost more at an auction before. You know the next picture, or at least you think you do.', 'Mindestens sieben Bieter waren noch im Rennen, als der Preis die 100 Millionen Dollar überschritt. Am Ende holten sich der chinesische Sammler Liu Yiqian und seine Frau Wang Wei diesen Akt für ihr Long Museum. Sie zahlten im November 2015 170,4 Millionen Dollar, in heutigem Geld etwa 225 Millionen. Nur ein einziges Kunstwerk hatte auf einer Auktion je mehr gekostet. Das nächste Bild kennst du, oder du glaubst es zumindest.', 'Amedeo Modigliani, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-18', 7, '5qh5krfaac', 'This is not the famous painting in Oslo but a pastel Munch made of the same scene. The bidding in New York took twelve minutes in May 2012. Then it was the most expensive work of art ever sold at an auction, at 119.9 million dollars or about 165 million in today''s money. The seller''s father had been a friend of Munch, and the money was meant for a new museum in Norway. Today''s last picture beat even that.', 'Das ist nicht das berühmte Gemälde in Oslo, sondern ein Pastell, das Munch von derselben Szene gemacht hat. Im Mai 2012 wurde in New York zwölf Minuten lang geboten. Dann war es das teuerste Kunstwerk, das je auf einer Auktion verkauft wurde, mit 119,9 Millionen Dollar oder etwa 165 Millionen in heutigem Geld. Der Vater des Verkäufers war ein Freund von Munch gewesen, und das Geld war für ein neues Museum in Norwegen gedacht. Das letzte Bild von heute hat sogar das übertroffen.', 'Edvard Munch, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-18', 8, 'j5ef9fakj9', 'On 18 November 2025 this portrait sold in New York for 236.4 million dollars. The bidding started at 130 million and went on for twenty minutes. No modern work of art has ever cost more at an auction, and only the Salvator Mundi from Monday''s story cost more at all. The Nazis had seized the picture from the Lederer family, and in 1948 it was given back to Elisabeth''s brother Erich. It then belonged to the collector Leonard Lauder.', 'Am 18. November 2025 wurde dieses Bildnis in New York für 236,4 Millionen Dollar versteigert. Das Bieten begann bei 130 Millionen und dauerte zwanzig Minuten. Kein Werk der Moderne hat auf einer Auktion je mehr gekostet, und überhaupt war nur der Salvator Mundi aus der Geschichte vom Montag teurer. Die Nationalsozialisten hatten das Bild der Familie Lederer weggenommen, und 1948 bekam es Elisabeths Bruder Erich zurück. Danach gehörte es dem Sammler Leonard Lauder.', 'Gustav Klimt, public domain (Wikimedia Commons)');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('yx6csn5z9u', 'daily:cecilia:1600-stefano-maderno-saint-cecilia', 'Saint Cecilia', 'Stefano Maderno', 1600, 'About 1600 (Wikipedia); the tomb was opened on 22 October 1599. One other source gives 1599.', null, 'marble', 'Santa Cecilia in Trastevere, Rome', 3, 'sculpture', 'https://nambatu.github.io/circart-preview/art/yx6csn5z9u.jpg', 'The saint lies on her side beneath the high altar of her church in Rome. Her face is turned away from us, and a thin cut shows on her neck. The white marble makes her look almost soft, like a sleeper under a sheet.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('t5dkwa33ts', 'daily:cecilia:1517-raphael-the-ecstasy-of-saint-cecilia', 'The Ecstasy of Saint Cecilia', 'Raphael', 1517, 'About 1516–17 according to Wikipedia; Commons photos from the Pinacoteca give about 1515–18.', 'High Renaissance', 'oil on panel, transferred to canvas', 'Pinacoteca Nazionale, Bologna', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/t5dkwa33ts.jpg', 'Cecilia stands among four saints: Paul, John the Evangelist, Augustine and Mary Magdalene. Above them a small choir of angels sings from an opening in the clouds. Napoleon''s troops took the picture to Paris, and it came back to Bologna after his fall.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('bmapkwhf4s', 'daily:cecilia:1895-john-william-waterhouse-saint-cecilia', 'Saint Cecilia', 'John William Waterhouse', 1895, 'Dated 1895 (Victorian Web; Wikimedia Commons).', 'Pre-Raphaelites', 'oil on canvas', 'Private collection', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/bmapkwhf4s.jpg', 'Cecilia sits asleep in a garden by the sea with a book on her lap. Behind her the sea shines, and two angels kneel and play their violins for her.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('3ftcr42exf', 'daily:cecilia:1772-thomas-gainsborough-the-linley-sisters-elizabeth-and-mary-li', 'The Linley Sisters (Elizabeth and Mary Linley)', 'Thomas Gainsborough', 1772, 'Painted between early 1771 and March 1772 (Dulwich Picture Gallery); shown at the Royal Academy in 1772 (Wikipedia). Retouched by the painter in 1785.', null, 'oil on canvas', 'Dulwich Picture Gallery, London', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/3ftcr42exf.jpg', 'The two sisters lean close together in a soft, feathery landscape that looks almost like a stage set. Gainsborough painted several members of the Linley family, who were all musicians.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('4sh9jn9fbu', 'daily:cecilia:1911-wassily-kandinsky-impression-iii-concert', 'Impression III (Concert)', 'Wassily Kandinsky', 1911, '1911 (Lenbachhaus via Google Arts & Culture; Finestre sull''Arte). The concert was on 2 January 1911.', 'Expressionism', 'oil on canvas', 'Städtische Galerie im Lenbachhaus, Munich', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/4sh9jn9fbu.jpg', 'A huge field of yellow pours across the canvas, and a big black shape rises out of it. Kandinsky called his paintings of this kind "impressions", because they began with something he had seen or heard.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('pamtw6m8uu', 'daily:cecilia:1665-johannes-vermeer-the-music-lesson-lady-at-the-virginals-w', 'The Music Lesson (Lady at the Virginals with a Gentleman)', 'Johannes Vermeer', 1665, 'About 1662–65 (Wikipedia); "early 1660s" according to the Royal Collection.', 'Dutch Golden Age', 'oil on canvas', 'Royal Collection, London', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/pamtw6m8uu.jpg', 'Light falls from the windows on the left across a tiled floor and a heavy carpet. A bass viol lies on the floor, as if waiting for a second player. In the mirror above the instrument you can even glimpse part of the painter''s easel.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('9kgp7a6ewa', 'daily:cecilia:1892-pierre-auguste-renoir-young-girls-at-the-piano', 'Young Girls at the Piano', 'Pierre-Auguste Renoir', 1892, '1892 (Musée d''Orsay via Google Arts & Culture; Wikipedia).', 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/9kgp7a6ewa.jpg', 'One girl sits at the piano while the other leans over to follow the notes. Renoir painted the scene in soft, warm strokes, without a single hard edge.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('xmsjvcv39w', 'daily:cecilia:1866-douard-manet-the-fifer', 'The Fifer', 'Édouard Manet', 1866, '1866 (Wikipedia; Britannica).', 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/xmsjvcv39w.jpg', 'The boy stands against a plain grey background with no floor and no horizon. His red trousers and black jacket are painted in flat areas of colour, almost like a playing card.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de, artist_bonus, movement_bonus, look_back) values ('2026-11-22', 'cecilia', 'Cecilia''s music', 'Cäcilias Musik', '22 November is the feast day of Saint Cecilia, the patron saint of music. Legend says that at her own wedding she sang to God in her heart while the instruments played. Today you follow her music through eight works: some show the saint herself, others the music she stands for. Your start card is her marble figure in Rome. Her tomb was opened under Cardinal Sfondrati, who had searched for her, and the sculptor Stefano Maderno said he carved her exactly as she was found. The first picture to place shows the same saint wide awake, listening to angels while her own instruments lie at her feet.', 'Der 22. November ist der Tag der heiligen Cäcilia, der Schutzpatronin der Musik. Der Legende nach sang sie bei ihrer eigenen Hochzeit in ihrem Herzen für Gott, während die Instrumente spielten. Heute folgst du ihrer Musik durch acht Werke: Manche zeigen die Heilige selbst, andere die Musik, für die sie steht. Deine Startkarte ist ihre Marmorfigur in Rom. Kardinal Sfondrati, der nach ihr gesucht hatte, ließ ihr Grab öffnen, und der Bildhauer Stefano Maderno sagte, er habe sie genau so gemeißelt, wie man sie fand. Das erste Bild zum Einordnen zeigt dieselbe Heilige hellwach: Sie lauscht den Engeln, und ihre eigenen Instrumente liegen zu ihren Füßen.', 'Eight works and one saint. Cecilia let her own instruments fall to hear the angels, yet over the centuries her music left the church and found its way into concert halls and living rooms. Happy St Cecilia''s Day, and maybe put on some music tonight.', 'Acht Werke und eine Heilige. Cäcilia ließ ihre eigenen Instrumente fallen, um den Engeln zuzuhören, und doch verließ ihre Musik im Lauf der Jahrhunderte die Kirche und fand ihren Weg in Konzertsäle und Wohnzimmer. Einen schönen Cäcilientag, und vielleicht legst du heute Abend etwas Musik auf.', true, true, false) on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, artist_bonus = excluded.artist_bonus, movement_bonus = excluded.movement_bonus, look_back = excluded.look_back, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-22', 0, 'yx6csn5z9u', null, null, 'Photo: NateBergin, CC BY 4.0 (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-22', 1, 't5dkwa33ts', 'According to Vasari, Cardinal Lorenzo Pucci ordered this altarpiece for a church in Bologna. Cecilia lets her little organ sink and looks up, because the angels'' song is sweeter than anything she can play. The instruments at her feet lie broken on the ground. In the next picture the roles are swapped: Cecilia has fallen asleep, and two angels kneel beside her and play for her.', 'Laut Vasari bestellte Kardinal Lorenzo Pucci dieses Altarbild für eine Kirche in Bologna. Cäcilia lässt ihre kleine Orgel sinken und blickt nach oben, denn der Gesang der Engel ist schöner als alles, was sie selbst spielen kann. Die Instrumente zu ihren Füßen liegen zerbrochen am Boden. Im nächsten Bild sind die Rollen vertauscht: Cäcilia ist eingeschlafen, und zwei Engel knien neben ihr und spielen für sie.', 'Raphael, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-22', 2, 'bmapkwhf4s', 'Waterhouse took the idea from a poem by Tennyson, which places the saint in a city by the sea. In 2000 the picture came up at Christie''s in London, and the composer Andrew Lloyd Webber bought it for about 6.6 million pounds. The next picture shows real singers: two sisters who sang on the concert stage.', 'Waterhouse nahm die Idee aus einem Gedicht von Tennyson, das die Heilige in eine Stadt am Meer versetzt. Im Jahr 2000 kam das Bild bei Christie''s in London unter den Hammer, und der Komponist Andrew Lloyd Webber kaufte es für rund 6,6 Millionen Pfund. Das nächste Bild zeigt echte Sängerinnen: zwei Schwestern, die auf der Konzertbühne standen.', 'John William Waterhouse, public domain (Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-22', 3, '3ftcr42exf', 'Elizabeth and Mary Linley were celebrated singers, and Elizabeth caused a scandal when she eloped with the playwright Richard Brinsley Sheridan. The family even asked Gainsborough to touch up the picture once, so that the dresses would look up to date. The next picture has no faces at all, only the memory of an evening at a concert.', 'Elizabeth und Mary Linley waren gefeierte Sängerinnen, und Elizabeth sorgte für einen Skandal, als sie mit dem Dramatiker Richard Brinsley Sheridan durchbrannte. Die Familie bat Gainsborough sogar einmal, das Bild zu überarbeiten, damit die Kleider wieder modern aussahen. Das nächste Bild hat gar keine Gesichter, nur die Erinnerung an einen Konzertabend.', 'Thomas Gainsborough, public domain (Google Art Project / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-22', 4, '4sh9jn9fbu', 'In Munich Kandinsky heard a concert of Arnold Schoenberg''s music and made sketches while it played. The big yellow mass is often read as the sound of the piano filling the hall, and the black shape as the piano itself. Soon he wrote Schoenberg a letter, the composer gladly wrote back, and a friendship began. The next room is much quieter: a young woman stands at a keyboard while a man watches her play.', 'In München hörte Kandinsky ein Konzert mit Musik von Arnold Schönberg und skizzierte, während gespielt wurde. Die große gelbe Fläche gilt oft als der Klang des Klaviers, der den Saal füllt, und die schwarze Form als der Flügel selbst. Bald schrieb er Schönberg einen Brief, der Komponist antwortete gern, und eine Freundschaft begann. Im nächsten Raum ist es viel stiller: Eine junge Frau steht an einem Tasteninstrument, und ein Mann sieht ihr beim Spielen zu.', 'Wassily Kandinsky, public domain (Google Art Project / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-22', 5, 'pamtw6m8uu', 'Look at the lid of the instrument. In Latin it says that music is a companion in joy and a balm in sorrow. Is this a lesson, or the start of a love story? Vermeer leaves it open. The next picture moves the music into a living room, where two girls bend over the notes together.', 'Schau auf den Deckel des Instruments. Dort steht auf Latein, dass die Musik eine Begleiterin der Freude und ein Trost im Schmerz ist. Ist das hier eine Unterrichtsstunde oder der Anfang einer Liebesgeschichte? Vermeer lässt es offen. Das nächste Bild holt die Musik ins Wohnzimmer, wo sich zwei Mädchen gemeinsam über die Noten beugen.', 'Johannes Vermeer, public domain (Google Art Project / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-22', 6, '9kgp7a6ewa', 'The French state asked Renoir, quite informally, for a painting for the Musée du Luxembourg in Paris. He painted several versions of these two girls, and the state bought this one. The last picture leaves the church and the living room behind: a boy from a military band stands alone in his uniform and plays.', 'Der französische Staat bat Renoir ganz formlos um ein Bild für das Musée du Luxembourg in Paris. Er malte mehrere Fassungen dieser beiden Mädchen, und der Staat kaufte diese hier. Das letzte Bild lässt Kirche und Wohnzimmer hinter sich: Ein Junge aus einer Militärkapelle steht allein in seiner Uniform da und spielt.', 'Pierre-Auguste Renoir, public domain (Google Art Project / Wikimedia Commons)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-22', 7, 'xmsjvcv39w', 'Manet sent this boy to the Salon in Paris, and the jury turned him away, saying the figure looked flat. The model was a fifer from the band of Napoleon III''s Imperial Guard, though some think Léon Leenhoff, who grew up in Manet''s home, posed as well. Today the boy plays in the Musée d''Orsay, in the same museum as Renoir''s girls at the piano.', 'Manet schickte diesen Jungen zum Salon in Paris, und die Jury wies ihn ab, weil die Figur zu flach wirke. Modell stand ein Pfeifer aus der Kapelle der Kaiserlichen Garde Napoleons III., manche glauben aber, dass auch Léon Leenhoff Modell saß, der in Manets Haushalt aufwuchs. Heute spielt der Junge im Musée d''Orsay, im selben Museum wie Renoirs Mädchen am Klavier.', 'Édouard Manet, public domain (Wikimedia Commons)');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('tn7t6tjpp2', 'daily:lautrec:1891-henri-de-toulouse-lautrec-moulin-rouge-la-goulue', 'Moulin Rouge – La Goulue', 'Henri de Toulouse-Lautrec', 1891, '1891 according to the Met and the Musée Toulouse-Lautrec.', 'Post-Impressionism', 'colour lithograph (poster)', 'The Metropolitan Museum of Art, New York (one of several prints)', 2, 'object', 'https://nambatu.github.io/circart-preview/art/tn7t6tjpp2.jpg', 'Lautrec''s first poster, made for the Moulin Rouge dance hall in Montmartre. In front dances Valentin, nicknamed "the Boneless", behind him the star dancer La Goulue.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('6ey66ff36s', 'daily:lautrec:1882-henri-de-toulouse-lautrec-young-routy-at-c-leyran', 'Young Routy at Céleyran', 'Henri de Toulouse-Lautrec', 1882, '1882 according to the Musée Toulouse-Lautrec (MTL.74); a second version of the same year is in the Neue Pinakothek, Munich.', 'Post-Impressionism', 'oil on canvas', 'Musée Toulouse-Lautrec, Albi', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/6ey66ff36s.jpg', 'Routy was a young man from Céleyran, the estate of Lautrec''s mother''s family near Narbonne. Lautrec painted him several times there.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('fnhg2hfea8', 'daily:lautrec:1901-henri-de-toulouse-lautrec-an-examination-at-the-faculty-of-medicin', 'An Examination at the Faculty of Medicine, Paris', 'Henri de Toulouse-Lautrec', 1901, '1901 according to the Musée Toulouse-Lautrec (MTL.216) and Hektoen International (painted August–September 1901).', 'Post-Impressionism', 'oil on canvas', 'Musée Toulouse-Lautrec, Albi', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/fnhg2hfea8.jpg', 'The candidate is Lautrec''s cousin Gabriel Tapié de Céleyran, a doctor, at his final doctoral examination in front of two professors.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('wcgue78dfb', 'daily:lautrec:1887-henri-de-toulouse-lautrec-portrait-of-vincent-van-gogh', 'Portrait of Vincent van Gogh', 'Henri de Toulouse-Lautrec', 1887, '1887 according to the Van Gogh Museum and Wikipedia.', 'Post-Impressionism', 'pastel on cardboard', 'Van Gogh Museum, Amsterdam', 2, 'drawing', 'https://nambatu.github.io/circart-preview/art/wcgue78dfb.jpg', 'Lautrec and van Gogh met at the studio of the painter Fernand Cormon in Paris. Theo van Gogh owned this pastel.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('spzze5g7qa', 'daily:lautrec:1895-henri-de-toulouse-lautrec-the-clowness-cha-u-kao', 'The Clowness Cha-U-Kao', 'Henri de Toulouse-Lautrec', 1895, '1895: signed and dated "HTLAUTREC 95" according to the French national museum database (Joconde); the Musée d''Orsay gives 1895 too.', 'Post-Impressionism', 'oil on cardboard', 'Musée d''Orsay, Paris', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/spzze5g7qa.jpg', 'Cha-U-Kao performed as a clown and dancer at the Moulin Rouge. Count Isaac de Camondo left the picture to the Louvre.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('a9mhdt6u5y', 'daily:lautrec:1888-henri-de-toulouse-lautrec-equestrienne-at-the-cirque-fernando', 'Equestrienne (At the Cirque Fernando)', 'Henri de Toulouse-Lautrec', 1888, '1887–88 according to the Art Institute of Chicago; counts as 1888, when it was finished and bought.', 'Post-Impressionism', 'oil on canvas', 'Art Institute of Chicago', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/a9mhdt6u5y.jpg', 'The rider may have been modelled on Suzanne Valadon, who later became a painter herself. Joseph Oller bought the picture for the Moulin Rouge.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('ypracm9u4m', 'daily:lautrec:1899-henri-de-toulouse-lautrec-at-the-circus-the-spanish-walk', 'At the Circus: The Spanish Walk', 'Henri de Toulouse-Lautrec', 1899, '1899 according to the Met; the Frick dates the whole circus series to 1899.', 'Post-Impressionism', 'graphite, pastel and charcoal on paper', 'The Metropolitan Museum of Art, New York (Robert Lehman Collection)', 2, 'drawing', 'https://nambatu.github.io/circart-preview/art/ypracm9u4m.jpg', 'One of a series of circus drawings made entirely from memory, without studies. The Met calls the step the "Spanish walk".', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('97vmgxcrtx', 'daily:lautrec:1893-henri-de-toulouse-lautrec-jane-avril-jardin-de-paris', 'Jane Avril (Jardin de Paris)', 'Henri de Toulouse-Lautrec', 1893, '1893 according to the Met and the Kemper Art Museum; the poster is signed "HTL 93".', 'Post-Impressionism', 'colour lithograph (poster)', 'Bibliothèque nationale de France, Paris (one of several prints; also at the Met)', 2, 'object', 'https://nambatu.github.io/circart-preview/art/97vmgxcrtx.jpg', 'Jane Avril ordered this poster herself to advertise her show at the Jardin de Paris, an open-air café-concert on the Champs-Élysées.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de, artist_bonus, movement_bonus, look_back) values ('2026-11-24', 'lautrec', 'Lautrec''s Paris', 'Lautrecs Paris', 'Today is Henri de Toulouse-Lautrec''s birthday. He comes from one of the oldest noble families in France, and he spends his nights in the dance halls and circus rings of Montmartre with a sketchbook in his hand. Eight of his works are waiting for you, and each one hides a clue. Look closely, place them, and at the end his story falls into place.', 'Heute hat Henri de Toulouse-Lautrec Geburtstag. Er stammt aus einer der ältesten Adelsfamilien Frankreichs und verbringt seine Nächte mit dem Skizzenbuch in den Tanzsälen und Zirkusmanegen vom Montmartre. Acht seiner Werke warten auf dich, und in jedem steckt ein Hinweis. Schau genau hin, leg sie an die richtige Stelle, und am Ende fügt sich seine Geschichte zusammen.', 'Case closed. From a young man painted in daylight at Céleyran to the dance halls and circus rings of Montmartre, Henri kept looking at the people that polite Paris preferred not to see, and he drew them with care instead of mockery. He died at 36, and his posters still hang all over the world.', 'Fall gelöst. Vom jungen Mann im Tageslicht von Céleyran bis zu den Tanzsälen und Zirkusmanegen vom Montmartre: Henri sah genau dort hin, wo das feine Paris lieber wegsah, und zeichnete diese Menschen mit Zuneigung statt mit Spott. Er starb mit 36 Jahren, und seine Plakate hängen heute in der ganzen Welt.', false, false, true) on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, artist_bonus = excluded.artist_bonus, movement_bonus = excluded.movement_bonus, look_back = excluded.look_back, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-24', 0, 'tn7t6tjpp2', 'Start with the grey shape in front: that''s her dance partner, Valentin, nicknamed "the Boneless". Behind him La Goulue kicks up her white petticoats, the brightest spot on the whole sheet, while the crowd is just flat black shadows. Remember that bold, flat look. Henri likes to leave out everything he doesn''t need, and it may help you with the cards to come.', 'Fang bei der grauen Gestalt ganz vorne an: Das ist ihr Tanzpartner Valentin, genannt „der Knochenlose“. Hinter ihm wirft La Goulue ihre weißen Unterröcke hoch, der hellste Fleck auf dem ganzen Blatt, während die Menge nur aus flachen schwarzen Schatten besteht. Merk dir diesen kräftigen, flächigen Stil. Henri lässt gern alles weg, was er nicht braucht, und das hilft dir vielleicht bei den nächsten Karten.', 'The Metropolitan Museum of Art, via Wikimedia Commons, public domain');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-24', 1, '6ey66ff36s', 'No dance hall here, only daylight. Look at the background: short, quick strokes of green and light, the way the Impressionists paint outdoors. Henri sets up his easel on his family''s estate at Céleyran in the south of France, and the young Routy sits for him. Here you can watch Henri still finding his own hand.', 'Kein Tanzsaal weit und breit, nur Tageslicht. Schau dir den Hintergrund an: kurze, schnelle Striche aus Grün und Licht, so wie die Impressionisten im Freien malen. Henri stellt seine Staffelei auf dem Familiengut Céleyran im Süden Frankreichs auf, und der junge Routy sitzt ihm Modell. Hier siehst du Henri noch auf der Suche nach seiner eigenen Handschrift.', 'Photo: Didier Descouens, via Wikimedia Commons');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-24', 2, 'fnhg2hfea8', 'Look at the paint first: dark, heavy and put on in broad strokes. On the left sits Henri''s cousin Gabriel at his final doctoral examination. Facing him are two professors, one of them in a gown with bright red trim. And if you looked very closely at the top left corner, you may have spotted a number that solved this case for you.', 'Schau zuerst auf die Farbe: dunkel, schwer und in breiten Strichen aufgetragen. Links sitzt Henris Cousin Gabriel bei seiner letzten Doktorprüfung. Ihm gegenüber sitzen zwei Professoren, einer davon im Talar mit leuchtend rotem Besatz. Und wer ganz genau in die linke obere Ecke geschaut hat, hat dort vielleicht eine Zahl entdeckt, die diesen Fall gelöst hat.', 'Photo: Didier Descouens, via Wikimedia Commons');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-24', 3, 'wcgue78dfb', 'A man in profile sits at a café table with a glass of absinthe in front of him. This is Vincent van Gogh, drawn by his friend Henri in pastel. Now look at the short, parallel strokes of bright colour. They look a lot like Vincent''s own way of painting. The two met as students in the Paris studio of the painter Fernand Cormon.', 'Ein Mann sitzt im Profil an einem Cafétisch, vor ihm ein Glas Absinth. Das ist Vincent van Gogh, gezeichnet von seinem Freund Henri mit Pastellkreide. Schau dir jetzt die kurzen, parallelen Striche in leuchtenden Farben an. Sie erinnern stark an Vincents eigene Malweise. Die beiden lernten sich als Schüler im Pariser Atelier des Malers Fernand Cormon kennen.', 'Van Gogh Museum, via Wikimedia Commons, public domain');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-24', 4, 'spzze5g7qa', 'Look at the yellow: the huge ruff fills half the picture and glows against the dark room. The clown is Cha-U-Kao from the Moulin Rouge, fastening her costume with her back half turned to you. Henri shows her calm and in her own world, not as a joke. Count Isaac de Camondo, a great collector, leaves this picture to the Louvre.', 'Schau auf das Gelb: Die riesige Halskrause füllt das halbe Bild und leuchtet vor dem dunklen Raum. Die Clownin ist Cha-U-Kao aus dem Moulin Rouge, die gerade ihr Kostüm schließt und dir halb den Rücken zukehrt. Henri zeigt sie ruhig und ganz bei sich, nicht als Witzfigur. Graf Isaac de Camondo, ein großer Sammler, vermacht das Bild dem Louvre.', 'Musée d''Orsay (Google Art Project), via Wikimedia Commons, public domain');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-24', 5, 'a9mhdt6u5y', 'Follow the curve of the ring: it sweeps right across the picture and gets cut off at the edges, as if Henri had only a moment to look. The ringmaster cracks his whip, the rider balances on her horse, and the clown at the left edge is half out of the picture. Joseph Oller, the man behind the Moulin Rouge, buys this picture for his dance hall.', 'Folge dem Bogen der Manege: Er schwingt quer durchs Bild und wird an den Rändern abgeschnitten, als hätte Henri nur einen Augenblick lang hinsehen können. Der Zirkusdirektor lässt die Peitsche knallen, die Reiterin hält sich auf dem Pferd, und der Clown am linken Rand ist halb aus dem Bild gerutscht. Joseph Oller, der Mann hinter dem Moulin Rouge, kauft das Bild für seinen Tanzsaal.', 'Art Institute of Chicago, via Wikimedia Commons, public domain');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-24', 6, 'ypracm9u4m', 'A horse lifts its front leg high, the rider in his top hat sits straight as a candle. Now the twist: there was no horse in front of Henri. He draws this whole circus series from memory, in a clinic where he is treated for alcoholism. The drawings help convince his doctors that he is well enough to leave. "I''ve bought my release with my drawings," he is said to have remarked.', 'Ein Pferd hebt das Vorderbein hoch, der Reiter mit Zylinder sitzt kerzengerade. Jetzt die Wendung: Vor Henri stand gar kein Pferd. Er zeichnet die ganze Zirkusserie aus dem Gedächtnis, in einer Klinik, in der er wegen seiner Alkoholsucht behandelt wird. Die Zeichnungen helfen, seine Ärzte zu überzeugen, dass es ihm gut genug geht, um zu gehen. „Ich habe mich mit meinen Zeichnungen freigekauft“, soll er gesagt haben.', 'The Metropolitan Museum of Art, Robert Lehman Collection, 1975, public domain');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-24', 7, '97vmgxcrtx', 'Look at the bottom of the poster: a hand and the long neck of a double bass, and the musician himself is cut off. That neck becomes a frame for the dancer kicking up her skirts on stage. She is Jane Avril, and she orders this poster from Henri herself, to advertise her own show at the Jardin de Paris.', 'Schau auf den unteren Teil des Plakats: eine Hand und der lange Hals eines Kontrabasses, der Musiker selbst ist abgeschnitten. Dieser Hals wird zum Rahmen für die Tänzerin, die auf der Bühne die Röcke schwingt. Sie heißt Jane Avril und bestellt das Plakat selbst bei Henri, um für ihre eigene Show im Jardin de Paris zu werben.', 'Bibliothèque nationale de France (Gallica), via Wikimedia Commons, public domain');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('fzwyphy4xv', 'daily:black-friday:1720-antoine-watteau-gersaint-s-shop-sign', 'Gersaint''s Shop Sign', 'Antoine Watteau', 1720, 'Painted in 1720 according to Richard Stemp and grandspeintres.com; some sources give 1720–21.', 'Rococo', 'oil on canvas', 'Charlottenburg Palace, Berlin', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/fzwyphy4xv.jpg', 'Frederick the Great bought the shop sign for his palaces in Prussia, which is how it came to Berlin. At some point it was cut into two halves, and the halves were joined again.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('cvwsh6n9sm', 'daily:black-friday:1962-andy-warhol-campbell-s-soup-cans', 'Campbell''s Soup Cans', 'Andy Warhol', 1962, '1962 according to MoMA and Sotheby''s; first shown at the Ferus Gallery, Los Angeles, in July 1962.', 'Pop art', 'synthetic polymer paint on 32 canvases', 'Museum of Modern Art, New York', 1, 'painting', 'https://nambatu.github.io/circart-preview/art/cvwsh6n9sm.jpg', 'Warhol is said to have eaten Campbell''s soup for lunch for many years. MoMA acquired the 32 canvases from Irving Blum in 1996.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('bf96qpnbqj', 'daily:black-friday:1514-quentin-massys-the-moneylender-and-his-wife', 'The Moneylender and His Wife', 'Quentin Massys', 1514, '1514 according to Wikipedia and the Fitzwilliam Museum.', 'Northern Renaissance', 'oil on panel', 'Louvre, Paris', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/bf96qpnbqj.jpg', 'The little round mirror on the table shows a man in a red hat by a window, outside the picture. The idea comes from Jan van Eyck.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('pwfbh9c9hz', 'daily:black-friday:1999-andreas-gursky-99-cent', '99 Cent', 'Andreas Gursky', 1999, '1999 according to Wikipedia, The Broad and MOCA Los Angeles.', null, 'chromogenic print', 'The Broad and MOCA, Los Angeles (prints of an edition)', 2, 'photograph', 'https://nambatu.github.io/circart-preview/art/pwfbh9c9hz.jpg', 'The photograph is huge: more than two metres tall and over three metres wide. Gursky made a second version, 99 Cent II Diptychon, in 2001.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('sce3d3pxan', 'daily:black-friday:1856-utagawa-hiroshige-suruga-ch-one-hundred-famous-views-of-ed', 'Suruga-chō (One Hundred Famous Views of Edo, no. 8)', 'Utagawa Hiroshige', 1856, '9th month of 1856 according to the Brooklyn Museum, Harvard Art Museums and LACMA.', 'Ukiyo-e', 'colour woodblock print', 'Many prints, e.g. Brooklyn Museum and LACMA', 2, 'print', 'https://nambatu.github.io/circart-preview/art/sce3d3pxan.jpg', 'The series One Hundred Famous Views of Edo has more than a hundred prints. Van Gogh copied two of them in oil.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('69nksm9tts', 'daily:black-friday:1987-barbara-kruger-untitled-i-shop-therefore-i-am', 'Untitled (I shop therefore I am)', 'Barbara Kruger', 1987, '1987 according to publicdelivery.org, Phaidon and Artchive (screenprint on vinyl).', null, 'screenprint on vinyl', 'Private collection', 2, 'print', 'https://nambatu.github.io/circart-preview/art/69nksm9tts.jpg', 'Kruger worked as a magazine designer before she became an artist, and her bold red-and-white look comes from there.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('shax5nhfaw', 'daily:black-friday:1551-pieter-aertsen-a-meat-stall-with-the-holy-family-giving', 'A Meat Stall with the Holy Family Giving Alms', 'Pieter Aertsen', 1551, 'Dated 1551 according to the North Carolina Museum of Art and Smarthistory.', 'Northern Renaissance', 'oil on panel', 'North Carolina Museum of Art, Raleigh', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/shax5nhfaw.jpg', 'Aertsen painted several versions of the meat stall; another one hangs in Uppsala, Sweden.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('4ykbshjub4', 'daily:black-friday:1882-douard-manet-a-bar-at-the-folies-berg-re', 'A Bar at the Folies-Bergère', 'Édouard Manet', 1882, '1882 according to the Courtauld (signed and dated) and Wikipedia.', 'Impressionism', 'oil on canvas', 'The Courtauld, London', 1, 'painting', 'https://nambatu.github.io/circart-preview/art/4ykbshjub4.jpg', 'It was the last major painting Manet completed and was shown at the Paris Salon of 1882.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de, artist_bonus, movement_bonus, look_back) values ('2026-11-27', 'black-friday', 'Shop till you drop', 'Kaufrausch', 'It''s Black Friday, and the shops are full. But people have been buying and selling for a very long time, and artists have always watched them do it. Eight pictures of shops and shoppers are waiting for you. Look for the clues and put them in order before the sale ends.', 'Es ist Black Friday, und die Läden sind voll. Aber gekauft und verkauft wird schon sehr lange, und Künstler haben dabei immer genau hingeschaut. Acht Bilder von Läden und Kundschaft warten auf dich. Such die Spuren und bring sie in die richtige Reihenfolge, bevor der Ausverkauf vorbei ist.', 'Case closed. Five hundred years of shopping, and the little scale has turned into a whole store in one photograph. The moneylender weighed every coin by hand, the soup cans lined up like goods on a shelf, and the slogan ended up on the shopping bag.', 'Fall gelöst. Fünfhundert Jahre Einkaufen, und aus der kleinen Waage ist ein ganzer Laden in einem einzigen Foto geworden. Der Geldwechsler wog jede Münze von Hand, die Suppendosen standen in Reih und Glied wie im Regal, und der Werbespruch landete auf der Einkaufstüte.', true, true, true) on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, artist_bonus = excluded.artist_bonus, movement_bonus = excluded.movement_bonus, look_back = excluded.look_back, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-27', 0, 'fzwyphy4xv', 'You are looking at an advertisement. Watteau paints this wide picture as the sign for the art shop of the dealer Gersaint in Paris. Look at the left: a portrait of King Louis XIV is going into a packing case, sold and ready to be sent off. On the right, elegant customers lean in to study the paintings for sale. The sign hangs outside the shop for only about two weeks, and then it is sold too.', 'Du schaust auf eine Werbung. Watteau malt dieses breite Bild als Ladenschild für die Kunsthandlung des Händlers Gersaint in Paris. Schau nach links: Ein Porträt von König Ludwig XIV. wandert in eine Kiste, verkauft und bereit zum Verschicken. Rechts beugen sich elegante Kunden über die Bilder, die zu haben sind. Nur etwa zwei Wochen hängt das Schild draußen am Laden, dann ist es selbst verkauft.', 'Charlottenburg Palace, via Wikimedia Commons, public domain');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-27', 1, 'cvwsh6n9sm', 'Thirty-two cans, one for every flavour Campbell''s sells. Look at the labels: tomato, clam chowder, black bean. Each one is painted by hand to look printed. At their first show in Los Angeles they stand on narrow ledges along the wall, like groceries on a supermarket shelf. The gallery owner Irving Blum keeps all thirty-two together and pays Warhol 1,000 dollars for them in instalments.', 'Zweiunddreißig Dosen, eine für jede Sorte, die Campbell''s verkauft. Schau auf die Etiketten: Tomate, Muschelsuppe, schwarze Bohnen. Jedes ist von Hand gemalt, damit es gedruckt aussieht. Bei ihrer ersten Ausstellung in Los Angeles stehen sie auf schmalen Leisten an der Wand, wie Waren im Supermarktregal. Der Galerist Irving Blum hält alle zweiunddreißig zusammen und zahlt Warhol dafür 1.000 Dollar in Raten.', 'Museum of Modern Art, New York');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-27', 2, 'bf96qpnbqj', 'Look at his hands. The man weighs coins and pearls on a tiny scale, very carefully. His wife holds a beautiful prayer book open in front of her, but her eyes are on the coins, not on the page. Money or faith, which one wins? Quentin Massys paints the question in Antwerp, a busy port full of merchants from all over Europe.', 'Schau auf seine Hände. Der Mann wiegt Münzen und Perlen auf einer winzigen Waage, ganz genau. Seine Frau hält ein prächtiges Gebetbuch aufgeschlagen vor sich, aber ihr Blick liegt auf den Münzen, nicht auf der Seite. Geld oder Glaube, was gewinnt? Quentin Massys malt diese Frage in Antwerpen, einem geschäftigen Hafen voller Kaufleute aus ganz Europa.', 'Louvre, via Wikimedia Commons, public domain');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-27', 3, 'pwfbh9c9hz', 'Rows and rows of colour, and every single thing costs the same. This is a photograph of a 99 Cents Only store in Los Angeles. Look up at the ceiling: the goods are reflected there too, and Gursky put that reflection in on the computer. In 2006 a print of this photo sells at Sotheby''s for more than two million dollars.', 'Reihe um Reihe voller Farbe, und jedes einzelne Ding kostet gleich viel. Das ist ein Foto aus einem 99-Cent-Laden in Los Angeles. Schau hoch zur Decke: Auch dort spiegeln sich die Waren, und diese Spiegelung hat Gursky am Computer eingesetzt. 2006 wird ein Abzug des Fotos bei Sotheby''s für mehr als zwei Millionen Dollar versteigert.', 'MOCA Los Angeles; © Andreas Gursky / ARS, courtesy Sprüth Magers');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-27', 4, 'sce3d3pxan', 'A street in Edo, today''s Tokyo, and Mount Fuji rises above it. The big shops on both sides belong to one business: Echigoya, the cloth shop of the Mitsui family. Its rule is new and simple, cash only, at the price on the tag. Echigoya grows into Mitsukoshi, one of Japan''s great department stores.', 'Eine Straße in Edo, dem heutigen Tokio, und darüber erhebt sich der Fuji. Die großen Läden auf beiden Seiten gehören zu einem einzigen Geschäft: Echigoya, dem Stoffladen der Familie Mitsui. Dort gilt eine neue, einfache Regel: nur Bargeld, zum angeschriebenen Preis. Aus Echigoya wird Mitsukoshi, eines der großen Kaufhäuser Japans.', 'LACMA, via Wikimedia Commons, public domain');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-27', 5, '69nksm9tts', 'Read the words: "I shop therefore I am." Barbara Kruger takes the philosopher Descartes'' famous line, "I think, therefore I am", and turns it into an advertising slogan. Look at the hand: it holds the words out to you like a business card. Her message ends up printed on real shopping bags.', 'Lies die Worte: „I shop therefore I am“, ich kaufe, also bin ich. Barbara Kruger nimmt den berühmten Satz des Philosophen Descartes, „Ich denke, also bin ich“, und macht daraus einen Werbespruch. Schau auf die Hand: Sie hält dir die Worte hin wie eine Visitenkarte. Ihre Botschaft landet am Ende auf echten Einkaufstüten.', 'Photo: krossbow (CC BY 2.0), via publicdelivery.org; © Barbara Kruger');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-27', 6, 'shax5nhfaw', 'Meat everywhere: an ox head stares out at you, and the whole front is piled high with things to buy. Now look past the food into the background. There Mary, on her donkey on the flight into Egypt, reaches back to give bread to a young beggar. A sign on the right even offers land for sale. Pieter Aertsen turns the old order around and puts the market in front of the Bible story.', 'Überall Fleisch: Ein Ochsenkopf starrt dich an, und der ganze Vordergrund ist voller Waren. Jetzt schau an den Waren vorbei nach hinten. Dort reicht Maria auf ihrem Esel, auf der Flucht nach Ägypten, einem jungen Bettler Brot. Rechts wird auf einem Schild sogar Land zum Verkauf angeboten. Pieter Aertsen dreht die alte Ordnung um und stellt den Markt vor die biblische Geschichte.', 'North Carolina Museum of Art, via Wikimedia Commons, public domain');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-27', 7, '4ykbshjub4', 'A barmaid looks at you across her counter, with a bowl of oranges and bottles in front of her. Look for the red triangle on some of the bottles: it is the label of Bass, a British beer. Behind her a mirror shows the crowd, and at the top left even the legs and green boots of a trapeze artist. But the reflection doesn''t quite match. The barmaid is called Suzon, and Manet paints the whole scene in his studio.', 'Eine Kellnerin schaut dich über ihre Theke an, vor ihr eine Schale Orangen und Flaschen. Such das rote Dreieck auf einigen Flaschen: Es ist das Etikett von Bass, einem britischen Bier. Hinter ihr zeigt ein Spiegel die Menge, und oben links sogar die Beine und grünen Stiefel eines Trapezkünstlers. Aber das Spiegelbild passt nicht ganz. Die Kellnerin heißt Suzon, und Manet malt die ganze Szene in seinem Atelier.', 'The Courtauld, via Wikimedia Commons, public domain');
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('h7yxs599e6', 'daily:annunciation:1534-lorenzo-lotto-recanati-annunciation', 'Recanati Annunciation', 'Lorenzo Lotto', 1534, 'About 1534 according to Wikipedia and the photo''s museum label; some sources say 1532, and a few scholars date it earlier.', 'Renaissance', 'oil on canvas', 'Museo civico Villa Colloredo Mels, Recanati', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/h7yxs599e6.jpg', 'Lotto spent his last years as a lay brother at the shrine of Loreto, a few kilometres from Recanati.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('gpbfn34b2x', 'daily:annunciation:1850-dante-gabriel-rossetti-ecce-ancilla-domini', 'Ecce Ancilla Domini!', 'Dante Gabriel Rossetti', 1850, '1850 according to Wikipedia and Britannica (painted 1849–50, shown in 1850).', 'Pre-Raphaelite', 'oil on canvas', 'Tate Britain, London', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/gpbfn34b2x.jpg', 'The title is Latin for "Behold the handmaid of the Lord", Mary''s answer to the angel. Rossetti was one of the founders of the Pre-Raphaelite Brotherhood.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('dy6y3mwjfc', 'daily:annunciation:1333-simone-martini-and-lippo-memmi-annunciation-with-st-margaret-and-st-ans', 'Annunciation with St. Margaret and St. Ansanus', 'Simone Martini and Lippo Memmi', 1333, '1333, dated in the signature on the frame (Uffizi, Smarthistory).', 'Sienese School', 'tempera and gold leaf on panel', 'Uffizi, Florence', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/dy6y3mwjfc.jpg', 'The altarpiece stayed in Siena Cathedral until 1799, when it was moved to Florence.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('suahzgkjpz', 'daily:annunciation:1898-henry-ossawa-tanner-the-annunciation', 'The Annunciation', 'Henry Ossawa Tanner', 1898, '1898 according to the Philadelphia Museum of Art and Wikipedia.', null, 'oil on canvas', 'Philadelphia Museum of Art', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/suahzgkjpz.jpg', 'Tanner studied with Thomas Eakins in Philadelphia and then moved to Paris, where he lived for the rest of his life.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('5heteturzv', 'daily:annunciation:1475-leonardo-da-vinci-annunciation', 'Annunciation', 'Leonardo da Vinci', 1475, 'About 1472–75 according to the Uffizi; Wikipedia gives about 1472–76. Counted here as 1475, the year it was finished at the latest by most accounts.', 'Renaissance', 'oil and tempera on panel', 'Uffizi, Florence', 1, 'painting', 'https://nambatu.github.io/circart-preview/art/5heteturzv.jpg', 'The painting came to the Uffizi in 1867 from the monastery of San Bartolomeo a Monteoliveto near Florence. For a long time it was thought to be by Ghirlandaio.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('7nj76gxbha', 'daily:annunciation:1891-paul-gauguin-ia-orana-maria-hail-mary', 'Ia Orana Maria (Hail Mary)', 'Paul Gauguin', 1891, '1891 according to the Met and Wikipedia.', 'Post-Impressionism', 'oil on canvas', 'The Metropolitan Museum of Art, New York', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/7nj76gxbha.jpg', 'It was one of the first big paintings Gauguin made in Tahiti. He wrote to a friend that he was rather pleased with it.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('eqnpdx8y8g', 'daily:annunciation:1436-jan-van-eyck-the-annunciation', 'The Annunciation', 'Jan van Eyck', 1436, 'About 1434/1436 according to the National Gallery of Art; Wikipedia says about 1434–36. Counted here as 1436.', 'Northern Renaissance', 'oil on canvas, transferred from panel', 'National Gallery of Art, Washington', 2, 'painting', 'https://nambatu.github.io/circart-preview/art/eqnpdx8y8g.jpg', 'The panel was once the left wing of a triptych. It hung in the Hermitage in St Petersburg until the Soviet government sold it to Andrew Mellon in 1930.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, active) values ('82733uchnq', 'daily:annunciation:1623-orazio-gentileschi-annunciation', 'Annunciation', 'Orazio Gentileschi', 1623, '1623 according to Wikipedia and arte.it; the painting was sent to Turin that year (Finestre sull''Arte).', 'Baroque', 'oil on canvas', 'Galleria Sabauda (Musei Reali), Turin', 3, 'painting', 'https://nambatu.github.io/circart-preview/art/82733uchnq.jpg', 'Orazio was the father of the painter Artemisia Gentileschi. He also worked for the queen of England and died in London.', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, visual_type = excluded.visual_type, image_url = excluded.image_url, trivia = excluded.trivia, updated_at = now();
insert into public.daily_themes (day, slug, title, title_de, intro, intro_de, outro, outro_de, artist_bonus, movement_bonus, look_back) values ('2026-11-29', 'annunciation', 'An angel calls', 'Ein Engel klopft an', 'Advent begins, the season of waiting, and the waiting starts with a visit. An angel comes to a young woman in Nazareth and tells her she will have a child. Painters have told this moment again and again, each in their own way. Look closely, follow the clues and put eight of these visits in order.', 'Der Advent beginnt, die Zeit des Wartens, und das Warten beginnt mit einem Besuch. Ein Engel kommt zu einer jungen Frau in Nazareth und sagt ihr, dass sie ein Kind bekommen wird. Maler haben diesen Moment immer wieder erzählt, jeder auf seine Weise. Schau genau hin, folge den Spuren und bring acht dieser Besuche in die richtige Reihenfolge.', 'Eight painters, one short conversation. Over the centuries the angel speaks in golden letters and then shrinks to a column of light, and Mary moves from a gold throne room into a plain bedroom. What stays the same is the moment itself: someone knocks, and the waiting begins.', 'Acht Maler, ein kurzes Gespräch. Über die Jahrhunderte spricht der Engel erst in goldenen Buchstaben und wird zuletzt zu einer Lichtsäule, und Maria zieht aus dem goldenen Raum in ein schlichtes Schlafzimmer. Gleich bleibt nur der Moment selbst: Jemand klopft an, und das Warten beginnt.', true, true, true) on conflict (day) do update set slug = excluded.slug, title = excluded.title, title_de = excluded.title_de, intro = excluded.intro, intro_de = excluded.intro_de, outro = excluded.outro, outro_de = excluded.outro_de, artist_bonus = excluded.artist_bonus, movement_bonus = excluded.movement_bonus, look_back = excluded.look_back, updated_at = now();
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-29', 0, 'h7yxs599e6', 'Start with the cat. It dashes across the room, as if it has seen something you can''t. The angel has just landed in the room with a white lily, and God leans down from the loggia outside. But Mary doesn''t turn to him. She turns to you, hands raised, as if you had walked in on the moment. Lorenzo Lotto painted it for the town of Recanati, and it is still there.', 'Fang mit der Katze an. Sie flitzt durchs Zimmer, als hätte sie etwas gesehen, das du nicht siehst. Gerade ist der Engel mit einer weißen Lilie im Zimmer gelandet, und draußen in der Loggia beugt sich Gott herab. Aber Maria dreht sich nicht zu ihm um. Sie dreht sich zu dir, die Hände erhoben, als wärst du mitten in diesen Moment hineingeplatzt. Lorenzo Lotto hat das Bild für die Stadt Recanati gemalt, und dort ist es bis heute.', 'Photo: Sailko, Wikimedia Commons, CC BY 3.0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-29', 1, 'gpbfn34b2x', 'Look how white this room is. Mary sits up on her bed in a nightgown and presses back against the wall, away from the lily the angel holds out. Gabriel has no wings at all, and small flames flicker at his feet. Dante Gabriel Rossetti leaves out the throne and the gold and paints a girl woken in her bedroom, and the critics attack it harshly. The model for Mary is his sister, the poet Christina Rossetti.', 'Schau, wie weiß dieses Zimmer ist. Maria sitzt im Nachthemd auf ihrem Bett und drückt sich an die Wand, weg von der Lilie, die der Engel ihr hinhält. Gabriel hat überhaupt keine Flügel, dafür züngeln kleine Flammen an seinen Füßen. Dante Gabriel Rossetti lässt Thron und Gold weg und malt ein Mädchen, das in seinem Schlafzimmer geweckt wird. Die Kritiker gehen hart mit ihm ins Gericht. Für Maria saß seine Schwester Modell, die Dichterin Christina Rossetti.', 'Tate Britain, via Google Arts & Culture and Wikimedia Commons, public domain');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-29', 2, 'dy6y3mwjfc', 'Read the gold. The angel''s greeting flies from his mouth in raised letters: "Ave gratia plena", hail, full of grace. Mary shrinks back into her dark cloak. Between them stands a vase of lilies, and above it the dove of the Holy Spirit. Two painters from Siena signed it together, Simone Martini and his brother-in-law Lippo Memmi, for an altar in Siena Cathedral. Their signature even carries the year, in Latin numerals.', 'Lies das Gold. Der Gruß des Engels kommt ihm in erhabenen Buchstaben aus dem Mund: „Ave gratia plena“, gegrüßt seist du, voll der Gnade. Maria weicht in ihren dunklen Mantel zurück. Zwischen den beiden steht eine Vase mit Lilien, darüber schwebt die Taube des Heiligen Geistes. Zwei Maler aus Siena haben gemeinsam signiert, Simone Martini und sein Schwager Lippo Memmi, für einen Altar im Dom von Siena. Ihre Signatur nennt sogar das Jahr, in römischen Ziffern.', 'Uffizi, Florence, via Wikimedia Commons, CC0');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-29', 3, 'suahzgkjpz', 'Where is the angel? Look for the light. Gabriel is nothing but a tall column of gold glowing at the edge of the room. Mary sits on her rumpled bed in plain peasant clothes, without a halo, and looks straight into it. Henry Ossawa Tanner, an African American painter living in Paris, paints it after a trip to Egypt and Palestine. It becomes the first of his paintings bought by an American museum.', 'Wo ist der Engel? Such das Licht. Gabriel ist nur eine hohe goldene Lichtsäule am Rand des Zimmers. Maria sitzt in einfacher Bauernkleidung auf ihrem zerwühlten Bett, ohne Heiligenschein, und schaut direkt hinein. Henry Ossawa Tanner, ein afroamerikanischer Maler, der in Paris lebt, malt das Bild nach einer Reise nach Ägypten und Palästina. Es ist das erste seiner Bilder, das ein amerikanisches Museum kauft.', 'Philadelphia Museum of Art, public domain');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-29', 4, '5heteturzv', 'Look at the angel''s wings. They are short and strong, modelled on a bird of prey. Gabriel kneels in a walled garden and holds out a lily, and Mary lifts her hand at her reading desk. Now look at her right arm: it seems too long. The Uffizi thinks the picture was meant to be seen from the side. The painter is Leonardo da Vinci, from the studio of his teacher Verrocchio, and the reading desk copies a tomb that Verrocchio made.', 'Schau dir die Flügel des Engels an. Sie sind kurz und kräftig, einem Raubvogel nachempfunden. Gabriel kniet in einem ummauerten Garten und reicht eine Lilie, Maria hebt an ihrem Lesepult die Hand. Und jetzt schau auf ihren rechten Arm: Er wirkt zu lang. Die Uffizien vermuten, dass das Bild von der Seite betrachtet werden sollte. Der Maler ist Leonardo da Vinci aus der Werkstatt seines Lehrers Verrocchio, und das Lesepult kopiert ein Grabmal, das Verrocchio geschaffen hat.', 'Uffizi, Florence, via Google Arts & Culture and Wikimedia Commons, public domain');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-29', 5, '7nj76gxbha', 'Find the angel first: half hidden among the blossoms on the left, with yellow wings. Two women with folded hands walk toward a mother who carries a child on her shoulder, and both mother and child wear halos. This is Mary with Jesus, painted as Tahitians by Paul Gauguin. The words in the corner, "Ia Orana Maria", are Tahitian for "Hail Mary". Much of the scene is borrowed from a photo Gauguin owned of a temple relief at Borobudur, on Java.', 'Such zuerst den Engel: halb versteckt zwischen den Blüten links, mit gelben Flügeln. Zwei Frauen mit gefalteten Händen gehen auf eine Mutter zu, die ein Kind auf der Schulter trägt, und Mutter und Kind tragen Heiligenscheine. Das sind Maria und Jesus, von Paul Gauguin als Tahitianer gemalt. Die Worte in der Ecke, „Ia Orana Maria“, heißen auf Tahitianisch „Gegrüßet seist du, Maria“. Vieles in der Szene stammt von einem Foto, das Gauguin besaß: ein Tempelrelief aus Borobudur auf Java.', 'The Metropolitan Museum of Art, New York, open access (CC0)');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-29', 6, 'eqnpdx8y8g', 'Tilt your head. Mary''s answer, "Ecce ancilla domini", behold the handmaid of the Lord, is painted upside down, so that God above can read it. Gabriel wears rainbow-coloured wings and a heavy jewelled cloak, and the dove glides down on golden rays. Even the floor tells stories: its tiles show Samson and David with Goliath. Jan van Eyck sets the whole visit inside a church.', 'Leg den Kopf schief. Marias Antwort, „Ecce ancilla domini“, siehe, ich bin die Magd des Herrn, steht auf dem Kopf, damit Gott sie von oben lesen kann. Gabriel trägt regenbogenfarbene Flügel und einen schweren, juwelenbesetzten Mantel, und die Taube gleitet auf goldenen Strahlen herab. Sogar der Boden erzählt: Seine Fliesen zeigen Samson und David mit Goliath. Jan van Eyck verlegt den ganzen Besuch in eine Kirche.', 'National Gallery of Art, Washington, via Google Arts & Culture and Wikimedia Commons, public domain');
insert into public.daily_theme_cards (day, position, card_id, chapter, chapter_de, credit) values ('2026-11-29', 7, '82733uchnq', 'Look up at the heavy red curtain. It is borrowed from Caravaggio, but here soft daylight falls into the room, and the dove of the Holy Spirit comes in through the window. Orazio Gentileschi paints it in Genoa and sends it, unasked, to the Duke of Savoy in Turin, whose family has its own Order of the Annunciation. The gift comes with a letter: Orazio hopes for a post at court. The duke keeps the painting, but Orazio never gets the post.', 'Schau hoch zum schweren roten Vorhang. Er ist bei Caravaggio abgeschaut, doch hier fällt sanftes Tageslicht in den Raum, und die Taube des Heiligen Geistes kommt durchs Fenster herein. Orazio Gentileschi malt das Bild in Genua und schickt es ungefragt an den Herzog von Savoyen in Turin, dessen Familie einen eigenen Orden der Verkündigung hat. Dem Geschenk liegt ein Brief bei: Orazio hofft auf eine Stelle am Hof. Der Herzog behält das Bild, aber die Stelle bekommt Orazio nie.', 'Galleria Sabauda, Turin, via Wikimedia Commons, public domain');
